function hasTerm(text, term) {
  return text.includes(term);
}

function normalizeForMatching(text) {
  return text
    .replaceAll('归藏', '歸藏')
    .replaceAll('简', '簡')
    .replaceAll('号', '號')
    .replaceAll('组', '組')
    .replaceAll('卦画', '卦畫')
    .replaceAll('卦辞', '卦辭')
    .replaceAll('释文', '釋文')
    .replaceAll('残简', '殘簡');
}

function collect(map, text) {
  return Object.entries(map)
    .filter(([term]) => hasTerm(text, term))
    .map(([term, note]) => ({ term, note }));
}

function splitSentences(text) {
  const pieces = text.replace(/\s+/g, '').split(/(?<=[。！？；])/u).filter(Boolean);
  return pieces.map((piece, index) => ({ text: piece, localIndex: index }));
}

