  ['帝乙', '帝乙。'],
  ['名羨', '帝乙名叫羨。'],
  ['三年王命南仲西拘昆夷城朔方夏六月周地震九年陟', '帝乙三年，命南仲向西拘捕昆夷，並在朔方築城。夏六月，周地震。九年，帝乙去世。'],
  ['帝辛', '帝辛。'],
  ['四年大蒐於黎作炮烙之刑', '四年，在黎地大規模搜捕，制定炮烙刑。'],
  ['五年夏築南單之臺雨土於亳', '五年夏天，在南單建造高臺；亳地降下土雨。'],
  ['六年西伯初禴於畢', '六年，西伯第一次在畢地舉行春祭。'],
  ['二十一年春正月諸侯朝周伯夷叔齊自孤竹歸於周', '二十一年春正月，諸侯到周朝見；伯夷、叔齊從孤竹歸附周國。'],
  ['二十二年冬大蒐於渭', '二十二年冬天，在渭水一帶大規模搜捕。'],
  ['二十三年囚西伯於羑里', '二十三年，把西伯囚禁在羑里。'],
  ['二十九年釋西伯諸侯逆西伯歸於程', '二十九年，釋放西伯；諸侯在途中迎接西伯回到程地。'],
  ['三十年春三月西伯率諸侯入貢', '三十年春三月，西伯率領諸侯入朝進貢。'],
  ['三十五年周大饑西伯自程遷於豐', '三十五年，周地大饑荒，西伯從程遷都到豐。'],
  ['三十七年周作辟雍', '三十七年，周人建造辟雍學宮。'],
  ['三十九年大夫辛甲出奔周', '三十九年，大夫辛甲逃亡到周。'],
  ['四十年周作靈臺王使膠鬲求玉於周', '四十年，周人建造靈臺；商王派膠鬲到周索求玉器。'],
  ['四十一年春三月西伯昌薨〈周文王葬畢郢西於豐三十里〉', '四十一年春三月，西伯姬昌去世（周文王葬在畢地，位於豐以西三十里）。'],
  ['四十七年內史向摯出奔周', '四十七年，內史向摯逃亡到周。'],
  ['四十八年夷羊見二日竝出', '四十八年，出現夷羊，兩個太陽同時出現。'],
  ['五十一年冬十一月戊子周師渡盟津而還王囚箕子殺王子比干微子出奔', '五十一年冬十一月戊子，周軍渡過盟津後返回；紂王囚禁箕子、殺死王子比干，微子逃亡。'],
  ['湯滅夏以至於受二十九王用嵗四百九十六年〈起癸亥終戊寅〉', '從商湯滅夏到紂王受，共二十九位君王，合計四百九十六年（從癸亥年到戊寅年）。'],
  ['PublicdomainPublicdomainfalsefalse', '原頁面附有公共領域標記。'],
  ['←捲上', '返回上卷。'],
  ['竹書紀年卷下', '《竹書紀年》下卷。'],
  ['周武王', '周武王。'],
  ['十四年王有疾周文公禱於壇墠作金縢', '十四年，武王生病；周文公在祭壇祈禱，撰作《金縢》。'],
  ['十五年肅慎氏來賓初狩方岳誥於沬邑冬遷九鼎於洛', '十五年，肅慎氏前來朝見；武王開始巡狩四方名山，在沬邑發布誥令；冬天把九鼎遷到洛邑。'],
  ['十六年箕子來朝秋王師滅蒲姑', '十六年，箕子前來朝見；秋天，王師滅掉蒲姑。'],
  ['十七年命王世子誦於東宮冬十有二月王陟年九十四', '十七年，命王太子誦居住東宮；冬十二月，武王去世，享年九十四歲。'],
  ['成王', '周成王。'],
  ['名誦', '成王名叫誦。'],
  ['元年丁酉春正月王即位命冡宰周文公總百官庚午周公誥諸侯於皇門夏六月葬武王於畢秋王加元服武庚以殷叛周文公出居於東', '元年丁酉春正月，成王即位，命冢宰周文公總管百官；庚午日，周公在皇門告誡諸侯。夏六月，武王葬在畢；秋天成王舉行冠禮。武庚以殷地反叛，周文公出居東方。'],
  ['六年大蒐於岐陽', '成王六年，在岐山南面大規模搜捕。'],
  ['十一年春正月王如豐唐叔獻嘉禾王命唐叔歸禾於周文公王命周平公治東都', '十一年春正月，成王到豐地；唐叔獻上嘉禾。成王命唐叔把禾穀送給周文公，又命周平公治理東都。'],
  ['約按周平公即君陳周公之子伯禽之弟', '按語說，周平公就是君陳，是周公的兒子、伯禽的弟弟。'],
  ['十二年王師燕師城韓王錫韓侯命', '十二年，王師和燕軍修築韓城；周王賜命給韓侯。'],
  ['十四年秦師圍曲城克之冬洛邑告成', '十四年，秦軍包圍曲城並攻克；冬天，洛邑建設完成。'],
  ['二十一年除治象周文公薨於豐', '二十一年，整治法象制度；周文公在豐地去世。'],
  ['二十二年葬周文公於畢', '二十二年，把周文公葬在畢地。'],
  ['二十四年於越來賓', '二十四年，于越前來朝見。'],
  ['二十五年王大會諸侯於東都四夷來賔冬十月歸自東都大事於太廟', '二十五年，成王在東都大會諸侯，四方夷族也來朝見；冬十月從東都回來，在太廟舉行大祭。'],
  ['三十年離戎來賓', '三十年，離戎前來朝見。'],
  ['三十三年王遊於卷阿召康公從歸於宗周命王世子釗如房逆女房伯祈歸於宗周', '三十三年，成王遊於卷阿，召康公跟隨，返回宗周；命太子釗到房地迎娶女子，房伯祈也回到宗周。'],
  ['三十四年雨金於鹹陽', '三十四年，鹹陽降下金屬般的異物。'],
  ['約按鹹陽天雨金三年國有大喪', '按語說，鹹陽降金後三年，國家發生大喪。'],
  ['三十七年夏四月乙丑王陟', '三十七年夏四月乙丑日，成王去世。'],
  ['康王', '周康王。'],
  ['名釗', '康王名叫釗。'],
  ['元年甲戌春正月王即位命冡宰召康公總百官諸侯朝於豐宮', '元年甲戌春正月，康王即位，命冢宰召康公總管百官，諸侯在豐宮朝見。'],
  ['三年定樂歌吉禘於先王申戒農官告於廟', '三年，制定樂歌，在先王廟舉行吉禘，重申對農官的告誡，並到宗廟告祭。'],
  ['六年齊太公薨', '六年，齊太公去世。'],
  ['九年唐遷於晉作宮而美王使人讓之', '九年，唐國遷到晉地，建造華美宮室；康王派人責讓其逾越。'],
  ['十二年夏六月壬申王如豐錫畢公命秋毛懿公薨十六年錫齊侯伋命王南巡狩至九江廬山', '十二年夏六月壬申，康王到豐地，賜命給畢公；秋天毛懿公去世。十六年，賜命給齊侯伋；康王南巡，到達九江、廬山。'],
  ['十九年魯侯禽父薨', '十九年，魯侯禽父去世。'],
  ['二十一年魯築茅闕門', '二十一年，魯國修築茅闕門。'],
  ['二十四年召康公薨', '二十四年，召康公去世。'],
  ['二十六年秋九月己未王陟', '二十六年秋九月己未日，康王去世。'],
  ['昭王', '周昭王。'],
  ['名瑕', '昭王名叫瑕。'],
  ['元年庚子春正月王即位復設象魏', '元年庚子春正月，昭王即位，重新設置象魏，公布法令。'],
  ['六年王錫郇伯命冬十二月桃李華', '六年，昭王賜命給郇伯；冬十二月，桃樹和李樹開花。'],
  ['穆王', '周穆王。'],
  ['名滿', '穆王名叫滿。'],
  ['元年己未春正月王即位作昭宮命辛伯餘靡冬十月築祗宮於南鄭', '元年己未春正月，穆王即位，建造昭宮，任命辛伯和餘靡；冬十月，在南鄭建造祗宮。'],
  ['自武王至穆王享國百年穆王以下都於西鄭', '從武王到穆王共一百年；穆王以後，周王都城在西鄭。'],
  ['八年春北唐來賓獻一驪馬是騄耳', '八年春，北唐前來朝見，獻上一匹黑鬃馬，名叫騄耳。'],
  ['九年築春宮〈王所居有鄭宮春宮〉', '九年，建造春宮（周王居住在鄭宮、春宮）。'],
  ['十一年王命卿士祭公謀父', '十一年，穆王任命祭公謀父為卿士。'],
  ['作虎牢', '建造虎牢。'],
  ['十五年春正月留昆氏來賓作重璧臺冬王觀於鹽澤〈一作王幸安邑觀鹽池非是〉', '十五年春正月，留昆氏前來朝見，建造重璧臺；冬天，穆王到鹽澤觀看（另一本作到安邑觀看鹽池，但不對）。'],
  ['十六年霍侯舊薨王命造父封於趙', '十六年，霍侯舊去世；穆王命造父，將趙地封給他。'],
  ['十八年春正月王居祗宮諸侯來朝', '十八年春正月，穆王居住在祗宮，諸侯前來朝見。'],
  ['二十一年祭文公薨', '二十一年，祭文公去世。'],
  ['二十四年王命左史戎夫作記', '二十四年，穆王命左史戎夫撰寫記錄。'],
  ['三十五年荊人入徐毛伯遷帥師敗荊人於泲', '三十五年，荊人入侵徐國；毛伯遷率軍在泲地擊敗荊人。'],
  ['三十九年王會諸侯於塗山', '三十九年，穆王在塗山會合諸侯。'],
  ['四十五年魯侯㵒薨', '四十五年，魯侯㵒去世。'],
  ['五十一年作呂刑命甫侯於豐', '五十一年，制定《呂刑》，在豐地命甫侯執行。'],
  ['五十五年王陟於祗宮', '五十五年，穆王在祗宮去世。'],
  ['共王', '周共王。'],
  ['名繄', '共王名叫繄。'],
  ['元年甲寅春正月王即位', '元年甲寅春正月，共王即位。'],
  ['四年王師滅宻', '四年，王師滅掉密國。'],
  ['九年春正月丁亥王使內史良錫毛伯遷命', '九年春正月丁亥，共王派內史良向毛伯遷賜命。'],
  ['十二年王陟', '十二年，共王去世。'],
  ['懿王', '周懿王。'],
  ['名堅', '懿王名叫堅。'],
  ['元年丙寅春正月王即位天再旦於鄭', '元年丙寅春正月，懿王即位；鄭地出現一天兩次天亮的異象。'],
  ['七年西戎侵鎬', '七年，西戎入侵鎬京。'],
  ['十三年翟人侵岐', '十三年，翟人入侵岐地。'],
  ['十五年王自宗周遷於槐裏', '十五年，懿王從宗周遷到槐里。'],
  ['十七年魯厲公擢薨', '十七年，魯厲公擢去世。'],
  ['二十五年王陟', '二十五年，懿王去世。'],
  ['懿王之世興居無節號令不時挈壺氏不能共其職諸侯於是攜徳', '懿王時期起居沒有節度，號令也不按時發布，掌管漏壺的官員無法完成職責；諸侯因此離心，背離王室的德政。'],
  ['孝王', '周孝王。'],
  ['名闢方', '孝王名叫闢方。'],
  ['五年西戎來獻馬', '五年，西戎前來獻馬。'],
  ['七年冬大雨電江漢水〈牛馬死是年厲王生〉', '七年冬天，大雨並伴隨雷電，江水、漢水暴漲（牛馬死亡；這一年厲王出生）。'],
  ['八年初牧於汧渭', '八年，開始在汧水、渭水一帶放牧。'],
  ['九年王陟', '九年，孝王去世。'],
  ['夷王', '周夷王。'],
  ['名燮', '夷王名叫燮。'],
  ['元年庚子春正月王即位', '元年庚子春正月，夷王即位。'],
  ['二年蜀人呂人來獻瓊玉賓於河用介珪', '二年，蜀人、呂人前來獻美玉，在河邊朝見，使用大玉圭作禮。'],
  ['三年王致諸侯烹齊哀公於鼎', '三年，夷王召集諸侯，把齊哀公放進鼎中烹殺。'],
  ['六年王獵於社林獲犀牛一以歸', '六年，夷王在社林打獵，捕獲一頭犀牛帶回。'],
  ['八年王有疾諸侯祈於山川王陟', '八年，夷王生病，諸侯向山川祈禱；夷王去世。'],
  ['厲王', '周厲王。'],
  ['元年戊申春正月王即位作夷宮命卿士榮夷公落楚人來獻龜貝', '元年戊申春正月，厲王即位，建造夷宮，任命榮夷公為卿士；落、楚人前來獻龜和貝。'],
  ['三年淮夷侵洛王命虢公長父殺之不克齊獻公山薨', '三年，淮夷入侵洛地；厲王命虢公長父討伐，但沒有取勝。齊獻公山去世。'],
  ['>注意：目前公開資料並未提供394支簡的完整、定本復原。', '注意：目前公開資料沒有提供394支竹簡的完整定本復原。'],
  ['以下是公開頁面所載的53條／節錄釋文；', '以下是公開頁面收錄的53條節錄釋文。'],
  ['王家臺秦簡《歸藏》編號者一百六十四支，未編號的殘簡二百三十支，共計三百九十四支，總字數約四千餘字。', '王家臺秦簡《歸藏》有編號竹簡164支，未編號殘簡230支，共394支，總字數約四千多字。'],
  ['由於殘缺過甚，至今尚未拼出一支整簡，順序也難以排定。', '由於殘缺嚴重，至今還沒有拼合出一支完整竹簡，簡文順序也很難確定。'],
  ['在這批竹簡重，共有七十組卦畫，其中十六組相同，除去相同數，不同的卦畫有五十四種。', '這批竹簡中共有七十組卦畫，其中十六組重複，扣除重複後，不同的卦畫有五十四種。'],
  ['卦畫皆以一表示陽爻，以∧表示陰爻。', '所有卦畫都用「一」表示陽爻，用「∧」表示陰爻。'],
  ['卦名有七十六個，其中重複者二十三個，實際卦名五十三個。', '卦名共有七十六個，其中二十三個重複，實際不同的卦名有五十三個。'],
  ['此外，卦辭也有一部分重複。', '此外，部分卦辭也有重複。'],
  ['竹簡有兩種，一種寬而薄，而另一種窄而厚。', '竹簡有兩種形制：一種寬而薄，另一種窄而厚。'],
  ['因此，我們推測，這批《歸藏》有兩種抄本。', '因此可以推測，這批《歸藏》材料有兩種抄本。'],
  ['秦簡《歸藏》的卦畫皆可與今本《周易》對應起來，卦名也與傳本《歸藏》、不帛書《周易》及今本《周易》大部分相同。', '秦簡《歸藏》的卦畫都能與今本《周易》相互對應，卦名也大多和傳本《歸藏》、帛書《周易》及今本《周易》相同。'],
  ['現摘錄部分釋文如下（本釋文以錄簡頭爲主，重複者只錄其一，但卦畫和卦名可互相補充者則皆錄下來。', '現在摘錄部分釋文如下；本釋文以竹簡開頭為主，重複內容只收錄一次，但能互相補充卦畫和卦名的仍一併收錄。'],
  ['釋文大致按馬國翰《玉函山房輯佚書》之《六十四卦》的順序排列，下面的編號爲清理時的原始編號，上面的編號爲臨時序列號。', '釋文大致按照馬國翰《玉函山房輯佚書·六十四卦》的順序排列；下方編號是清理時的原始編號，上方編號是臨時序列號。'],
  ['竹簡殘斷者以◇標出，字跡模糊、無法辨識者以□標出，通假字、異體字不另註明，但據文意明顯有脫字者以【】補足。', '竹簡殘斷用◇標示，字跡模糊或不能辨識用□標示；通假字、異體字不另加說明，依文意明顯脫漏的字用【】補足。'],
  ['本釋文是剛清洗出來時所作的原始釋文，未經仔細校對，錯誤之處在所難免，若有牴觸，以將來正式出版爲準）：', '這份釋文是竹簡剛清洗後整理的初步釋文，尚未仔細校對，難免有錯誤；若有矛盾，應以未來正式出版的定本為準。'],
  ['2、天目朝＝不利爲草木贊＝偁下□◇181（知北逰按：此簡頭有乾卦卦畫）', '編號2的簡文大意是「天目朝……不利於草木……」；其中有不能辨識的字，編號181的簡頭有乾卦卦畫。'],
  ['下同）◇', '以下同樣有殘缺字。'],
  ['30、【蹇】□◇', '編號30可辨識出「蹇」卦名，另有模糊字和殘缺處。'],
  ['43、（知北逰按：此字上艹下晉，《集韻》以爲“茜”之或體，即晉卦。', '編號43的字形上部是艹、下部近「晉」；《集韻》認為是「茜」的異體，這裡指晉卦。'],
  ['46、□□（知北逰按：此簡頭有未濟卦畫）□□□攴卜□□□◇', '編號46有多處不能辨識；簡頭有未濟卦卦畫，全文仍有殘缺。'],
  ['知北逰按：以上根據王明欽《王家臺秦墓竹簡概述》（2000年北京大學新出簡帛國際學術研討會論文，手寫本）抄錄，開篇一段介紹即王先生之文；', '整理者說：以上內容抄錄自王明欽《王家臺秦墓竹簡概述》；開頭的介紹就是王先生原文。'],
  ['原簡頭具有卦畫，茲從略，唯卦名用字與《周易》不同者用按語說明；', '原竹簡開頭有卦畫，這裡省略；只有卦名用字和《周易》不同時，才用按語說明。'],
  ['打不出來的古體字亦用按語描述。', '無法輸入的古體字，也用按語描述字形。'],
  ['如有疑問請覈對王先生原稿。', '如有疑問，請核對王先生的原稿。'],
  ['惟十有三年，春，大會於孟津。', '十三年春天，諸侯在孟津大會。'],
  ['惟天地，萬物父母；', '天地是萬物的父母；'],
  ['惟人，萬物之靈。', '人是萬物之中最有靈性的。'],
  ['亶聰明，作元後，元後作民父母。', '真正聰明的人才能成為大君，大君要成為百姓的父母。'],
  ['今商王受，弗敬上天，降災下民，沈湎冒色，敢行暴虐。', '現在商王受不敬畏上天，給百姓降下災禍，沉溺酒色，竟敢施行暴虐。'],
  ['罪人以族，官人以世。', '他按族誅殺罪人，又讓官職世代承襲。'],
  ['惟宮室、臺榭、陂池、侈服，以殘害於爾萬姓。', '他建造宮室、高臺、池沼，製作奢侈服飾，用這些事殘害你們百姓。'],
  ['焚炙忠良，刳剔孕婦。', '他焚燒、炮烙忠良之士，剖殺懷孕的婦女。'],
  ['「皇天震怒，命我文考，肅將天威，大勛未集。', '上天震怒，命令我的先父文王恭敬地承受天威，但討伐的大功尚未完成。'],
  ['犧牲粢盛，既於兇盜。', '祭祀用的牲畜和穀物，已經被兇惡的盜賊奪取。'],
  ['』天佑下民，作之君、作之師。', '上天保佑下民，為他們建立君主，也建立師長。'],
  ['惟其克相上帝，寵綏四方。', '君主只有能夠輔助上帝，才能使四方得到恩寵和安定。'],
  ['有罪無罪，予曷敢有越厥志？', '不論有罪或無罪，我怎敢違背上天的意志呢？'],
  ['同力度德，同德度義，受有臣億萬，惟億萬心。', '比較力量要看德行，比較德行要看義理；商王雖有億萬臣民，卻各懷異心。'],
  ['予有臣三千，惟一心。', '我有三千臣下，卻同心同德。'],
  ['商罪貫盈，天命誅之，予弗順天，厥罪惟鈞。', '商朝的罪惡已經滿盈，上天命令我誅討它；我若不順從上天，罪責就和紂王一樣。'],
  ['予小子夙夜祗懼，受命文考，類於上帝，宜於冢土，以爾有眾，厎天之罰。', '我這個小子日夜敬畏，接受先父文王的命令，向上天祭告，又在大地神祇前舉行禮儀，率領你們眾人完成上天的懲罰。'],
  ['天矜於民，民之所欲，天必從之。', '上天憐憫百姓，百姓所希望的，上天一定順從。'],
  ['爾尚弼予一人，永清四海。', '你們要輔佐我，使四海永遠清平。'],
  ['時哉！', '時機到了！'],
  ['弗可失。', '不可錯失。'],
  ['惟戊午，王次於河朔。', '戊午日，武王駐紮在黃河北岸。'],
  ['羣後以師畢會。', '各地諸侯率軍全部會合。'],
  ['西土有眾，鹹聽朕言。', '西方各地的眾人，都聽我說。'],
  ['今商王受，力行無度，播棄犁老，暱比罪人。', '現在商王受肆意行事毫無法度，拋棄賢老，親近罪人。'],
  ['淫酗肆虐，臣下化之。', '他沉溺酒色、放縱暴虐，臣下也受到他的影響。'],
  ['朋家作仇，脅權相滅，無辜籲天，穢德彰聞。', '他結黨營私、互相仇視，以權勢脅迫彼此殘害；無辜的人向上天呼喊，污穢的德行已廣為人知。'],
  ['惟天惠民，惟闢奉天。', '上天只會施恩給百姓，君主應當奉行上天的意志。'],
  ['惟受罪浮於桀，剝喪元良，賊虐諫輔，謂己有天命，謂敬不足行，謂祭無益，謂暴無傷，厥監惟不遠，在彼夏王。', '商王受的罪行超過夏桀，剝奪並殺害賢良，殘害進諫輔弼之臣；他自稱擁有天命，說敬天不必實行、祭祀沒有用、暴虐也不會受害。他的鑑戒並不遙遠，就在夏王身上。'],
  ['「天其以予乂民，朕夢協朕卜，襲於休祥，戎商必克，受有億兆夷人，離心離德，予有亂臣十人，同心同德。', '上天大概是要讓我治理百姓；我的夢與占卜相合，又接連出現吉祥徵兆，我們一定能攻克商朝。商王受雖有億萬普通人，卻離心離德；我只有十位能治理國家的臣子，卻同心同德。'],
  ['雖有周親，不如仁人。', '即使有周王室的親族，也不如任用仁德的人。'],
  ['天視自我民視，天聽自我民聽。', '上天所看，是透過百姓所看；上天所聽，是透過百姓所聽。'],
  ['百姓有過，在予一人。', '百姓若有過錯，責任在我一人。'],
  ['勖哉夫子，罔或無畏，寧執非敵。', '努力吧，將士們，不要有任何人不心存敬畏；寧可擒獲敵人，也不可放過他們。'],
  ['嗚呼！', '唉！'],
  ['我西土君子，天有顯道，厥類惟彰。', '我們西方的君子啊，上天有明顯的正道，各種事理都清楚彰明。'],
  ['今商王受，狎侮五常，荒怠弗敬。', '現在商王受輕慢、侮辱五常，荒怠政事而不知敬畏。'],
  ['自絕於天，結怨於民，斮朝涉之脛，剖賢人之心。', '他自己斷絕與上天的關係，又和百姓結怨；砍斷早晨涉水者的腿，剖開賢人的心。'],
  ['作威殺戮毒痡四海。', '他逞威殺戮，使毒害遍及四海。'],
  ['崇信奸回，放黜師保，屏棄典刑，囚奴正士，郊社不修，宗廟不享，作奇技淫巧以悅婦人。', '他尊信奸邪反覆的人，放逐太師、太保，拋棄典章刑法，把正直之士囚禁為奴；不修郊社，不祭宗廟，製作奇異淫巧的玩物討婦人歡心。'],
  ['上帝弗順，祝降時喪。', '上帝不再順從他，命令降下這場禍亡。'],
  ['爾其孜孜，奉予一人，恭行天罰。', '你們要勤勉不懈，奉助我一人，恭敬地執行上天的懲罰。'],
  ['功多有厚賞，不迪有顯戮。', '功勞多的給予厚重賞賜，不肯前進效力的施以明顯刑戮。'],
  ['惟我文考，若日月之照臨，光於四方，顯於西土。', '我的先父文王，如日月照臨天下，光明遍及四方，在西土尤其顯著。'],
  ['惟我有周，誕受多方。', '我們周國因此廣泛接受四方的歸附。'],
  ['予克受，非予武，惟朕文考無罪。', '如果我能戰勝商王受，不是因為我武力強大，而是因為我的先父文王沒有罪過。'],
  ['受克予，非朕文考有罪，惟予小子無良。', '如果商王受能戰勝我，也不是因為我的先父文王有罪，而是因為我這個小子沒有德行。'],
  ['我友邦冢君，御事、司徒、司馬、司空、亞、旅、師氏、千夫長、百夫長及庸、蜀、羌、髳、微、盧一作「纑」、彭、濮人。', '我的友邦諸侯、各位執事，以及司徒、司馬、司空、亞、旅、師氏、千夫長、百夫長，還有庸、蜀、羌、髳、微、盧、彭、濮等地的人。'],
  ['牝雞之晨，惟家之索。', '母雞若在清晨啼叫，家道就會衰敗。'],
  ['』今商王受，惟婦言是用。', '現在商王受只聽從婦人的話。'],
  ['昏棄厥肆祀，弗答；', '他昏亂地拋棄先祖祭祀，不能回報祖先的恩德；'],
  ['昏（泯）棄厥遺', '他昏亂地拋棄先王遺留下來的教訓。'],
  ['王一作「任」父母弟，不', '他不任用王室的父兄弟弟。'],
  ['迪一作「用」（由）。', '他不任用王室的父兄弟弟。'],
  ['俾暴虐於百姓，以姦宄於商邑。', '反而讓奸人殘暴對待百姓，在商都製造奸邪禍亂。'],
  ['今予發，惟', '現在我姬發，將要'],
  ['恭一作「共、龔」行天之罰。', '恭敬地和諸侯一起執行上天的懲罰。'],
  ['夫子勖哉！', '將士們，努力吧！'],
  ['勖哉夫子！', '將士們，努力吧！'],
  ['尚桓桓，', '你們要勇猛威武，'],
  ['如虎、如貔、如熊、如羆一作「如虎如羆，如豺如離」，於商郊；', '像虎、貔、熊、羆一樣，在商都郊外作戰；'],
  ['弗迓克奔，以役西土。', '不要阻攔已經逃跑的敵人，好完成西方土地交付的使命。'],
  ['爾所弗勖，其於爾躬有戮。', '你們如果不努力，自己就會受到殺戮的刑罰。'],
  ['厥四月哉生明，王來自商至於豐。', '四月初，武王從商地回到豐地。'],
  ['歸馬於華山之陽，放牛於桃林之野，示天下弗服。', '把馬放回華山南面，把牛放到桃林野外，向天下表示不再使用武力。'],
  ['丁未，祀於周廟，邦甸、侯、衛，駿奔走，執豆籩。', '丁未日，在周的宗廟舉行祭祀；甸服、侯服和衛服的諸侯迅速奔走，捧持祭器供獻。'],
  ['越三日庚戌，柴望大告武成。', '三天後的庚戌日，燔柴祭天、望祭山川，大告武王克商成功。'],
  ['既生魄，庶邦冢君，暨百工，受命於周。', '月亮初生魄後，各國諸侯和百官都接受周王的命令。'],
  ['羣後，惟先王建邦啟土。', '諸侯啊，先王建立國家、開拓土地，'],
  ['公劉克篤前烈，至於大王，肇基王跡，王季其勤王家。', '公劉能厚實地承繼前人的功業；到了大王古公亶父，開始奠定王業的道路；王季又勤勉經營王室。'],
  ['我文考文王，克成厥勛，誕膺天命，以撫方夏。', '我的先父文王完成了這些功勳，承受上天的大命，安撫四方華夏。'],
  ['大邦畏其力，小邦懷其德。', '大國畏懼他的力量，小國感念他的德行。'],
  ['惟九年，大統未集。', '到了第九年，天下的大統仍未完全聚集。'],
  ['予小子其承厥志。', '我這個小子一定要承繼先王的志向。'],
  ['厎商之罪，告於皇天后土，所過名山大川。', '我把商朝的罪行告訴皇天后土，以及所經過的名山大川。'],
  ['予小子既獲仁人，敢祇承上帝，以遏亂略。', '我這個小子既已得到仁人輔佐，敢於恭敬承受上帝的命令，以阻止禍亂計謀。'],
  ['華夏蠻貊，罔不率俾，恭天成命。', '華夏和蠻夷各族沒有不遵從的，都恭敬奉行上天已成的命令。'],
  ['肆予東徵，綏厥士女。', '所以我向東征伐，使那裡的男女得到安定。'],
  ['惟其士女，篚厥玄黃，昭我周王。', '那裡的男女用竹篚盛著黑色和黃色的絲帛，來彰顯對周王的敬意。'],
  ['天休震動，用附我大邑周。', '上天的美善威勢震動四方，使眾人歸附我們周國。'],
  ['惟爾有神，尚克相予，以濟兆民，無作神羞。', '你們這些神明，希望能夠輔助我，救濟億萬百姓，不要使神明蒙受羞恥。'],
  ['」既戊午，師逾孟津，癸亥，陳於商郊，俟天休命。', '戊午日，軍隊渡過孟津；癸亥日，在商都郊外列陣，等待上天的美善命令。'],
  ['甲子昧爽，受率其旅若林，會於牧野。', '甲子日黎明，商王受率領像森林一樣眾多的軍隊，在牧野會戰。'],
  ['罔有敵於我師，前徒倒戈，攻於後以北，血流漂杵。', '商軍沒有力量抵抗我軍，前面的士兵倒轉兵器，從後方攻擊並逃跑，血流多到能漂起舂米杵。'],
  ['一戎衣，天下大定。', '武王一度穿起軍衣出征，天下便大致安定。'],
  ['釋箕子囚，封比干墓，式商容閭。', '釋放被囚的箕子，修整比干的墓，在商容的里門立表彰牌坊。'],
  ['散鹿臺之財，發鉅橋之粟。', '散發鹿臺府庫的財物，開出鉅橋倉庫的糧食。'],
  ['大賚於四海，而萬姓悅服。', '把恩賜廣施四海，天下百姓都喜悅而服從。'],
  ['列爵惟五，分土惟三。', '爵位分為五等，土地分為三等。'],
  ['建官惟賢，位事惟能。', '設置官職只任用賢人，安排職位只看才能。'],
  ['重民五教。', '重視教導百姓遵行五種倫理。'],
  ['惟食喪祭。', '國家要妥善處理百姓的飲食、喪事和祭祀。'],
  ['惇信明義，崇德報功，垂拱而天下治。', '敦厚守信，彰明義理，尊崇德行、酬報功勞；君王垂衣拱手，天下就能得到治理。'],
  ['洪範一作「鴻範」', '《洪範》，一種版本作《鴻範》。'],
  ['惟一作「維」十有三祀，王訪於箕子。', '十三年，武王前往訪問箕子；其中「惟」有版本作「維」。'],
  ['嗚呼一作「於乎、烏嘑」！', '唉！這個感嘆詞另有「於乎」「烏嘑」等異文。'],
  ['箕子。', '箕子。'],
  ['惟《宋世家》作「維」，篇內同天陰騭下民，相協厥居，我不知其彝倫', '《宋世家》作「維」；上天默默安定百姓，使他們協調居處，但我不知道常道的'],
  ['攸《五行志》作「逌」，篇內同', '「攸」，《五行志》作「逌」，篇內同。'],
  ['敘《宋世家》作「序」，篇內同。', '「敘」，《宋世家》作「序」，篇內同。'],
  ['陻一作「伊」', '「陻」有版本作「伊」。'],
  ['洪熹平石經、《宋世家》作「鴻」，篇內同。', '熹平石經和《宋世家》作「鴻」，篇內同。'],
  ['水，', '水，'],
  ['不一作「弗」畀洪範九疇，彝倫攸', '如果不把《洪範》的九類大法賜下，常道就會'],
  ['斁一作「釋」。', '「斁」有版本作「釋」。'],
  ['嚮一作「饗」用五福，', '「嚮」有版本作「饗」；上天降下五種福分，'],
  ['威一作「畏」用六極。', '「威」有版本作「畏」；上天降下六種極端禍患。'],
  ['潤下作鹹，炎上作苦，曲直作酸，從革作辛，稼穡作甘。', '水向下流形成鹹味，火向上燃形成苦味，木的曲直形成酸味，金能變革形成辛味，土能種植形成甘味。'],
  ['恭作肅，從作', '恭敬表現為嚴肅，順從表現為'],
  ['乂一作「艾」，明作', '「乂」有版本作「艾」；明辨表現為'],
  ['晢一作「悊」，聰作謀（敏），睿作聖。', '明辨有智慧，聰敏表現為謀略，睿智表現為聖明；其中「晢」有版本作「悊」，「聰」有版本作「敏」。'],
  ['箕子。', '箕子（人名）。'],
  ['水，', '水（五行之一），'],
  ['」[1]', '（原文校注編號一。）'],
  ['曆一作「歷」數。', '「曆數」的「曆」有版本作「歷」。'],
  ['」[2]', '（原文校注編號二。）'],
  ['「五、皇極：皇建其有極，斂時五福，用敷錫厥庶民。', '第五是皇極：君王建立最高準則，收聚五種福分，廣泛賜給百姓。'],
  ['惟時厥庶民於汝極，錫汝保極。', '百姓會因你的準則而歸向你，也會賜助你守住最高準則。'],
  ['凡厥庶民，無有淫朋；', '所有百姓都不可結交放縱的朋黨；'],
  ['人無有比德，惟皇作極。', '人不可互相勾結爭競，只有君王建立最高準則。'],
  ['不協於極，不', '不合於最高準則，就不'],
  ['罹一作「麗、離」於咎，皇則受之。', '陷入罪咎；「罹」有版本作「麗」或「離」，君王就承擔治理的責任。'],
  ['時人斯其惟皇之極。', '這樣人民才會歸依君王的最高準則。'],
  ['無虐煢獨一作「毋侮鰥寡、無侮鰥寡」，而畏高明。', '不要欺凌孤苦無依的人，也要敬畏有德有位的賢明者。'],
  ['羞一作「循、脩」其行，而邦其昌。', '修治自己的行為，國家就會昌盛；「羞」有版本作「循」或「脩」。'],
  ['凡厥正人，既富方穀，汝弗能使有好於而家，時人斯其辜。', '所有正直的人，富足後才能行善；如果你不能使他們在家國中得到善待，這就是你的罪過。'],
  ['於其無好{德}，汝雖錫之福，其作汝用咎。', '對沒有善德的人，即使你賜給他福分，他也會把它變成你的禍患。'],
  ['無一作「熹平石經作「毋」，下同」偏無', '不要偏私，不要'],
  ['陂一作「頗」，遵王之義；', '偏曲，遵循君王的義理；「陂」有版本作「頗」。'],
  ['無有作', '不要有人'],
  ['好一作「𡚽」，遵王之道；', '作惡，遵循君王的正道；「好」有版本作「𡚽」。'],
  ['無有作惡，遵王之路。', '不要作惡，遵循君王的道路。'],
  ['無偏無黨，王道蕩蕩；', '不要偏私、不要結黨，王道就會廣大平坦；'],
  ['無黨無偏，王道', '不要結黨、不要偏私，王道就'],
  ['平平一作「便便」；', '平正；「平平」有版本作「便便」。'],
  ['無反無側，王道正直。', '不要反覆偏斜，王道就會正直。'],
  ['會其有極，歸其有極。', '眾人都會聚於最高準則，歸依最高準則。'],
  ['皇一作「王」極之敷言，是', '皇極廣泛宣示的言語，就是'],
  ['彝一作「夷」是訓，於帝其訓。', '永恆的教訓，君王應當遵循這個教訓。'],
  ['凡厥庶民極之敷言，是訓是行，以近天子之光。', '百姓對皇極廣泛宣示的話，要奉為教訓並實行，以接近天子的光明。'],
  ['」[4]', '（原文校注編號四。）'],
  ['平康正直，彊弗友剛克，', '平和、安康、正直；強硬而不與人親善的，靠剛強取勝；'],
  ['燮一作「內」友柔克；', '調和親善的，靠柔和取勝；「燮」有版本作「內」。'],
  ['沈潛剛克，高明柔克。', '深沉潛藏的，以剛強取勝；高明外露的，以柔和取勝。'],
  ['惟闢作福，惟闢作威，惟闢玉食，臣無有作福、作威、玉食；', '只有君王可以施福、施威、享用精美食物；臣下不可擅自施福、施威、享用這些待遇；'],
  ['臣之有作福、作威、玉食，其害於而家、兇於而國。', '臣下若擅自施福、施威、享用精美食物，就會危害你的家族、禍害你的國家。'],
  ['人用側頗', '人因此偏斜不正。'],
  ['僻一作「闢」，民用僭', '「僻」有版本作「闢」；百姓就會僭越。'],
  ['忒一作「慝」。', '「忒」有版本作「慝」。'],
  ['凡七卜，五佔用，二衍忒[7]。', '總共占卜七次，其中五次得到相同判斷而採用，兩次出現差異；「衍忒」後有校注編號七。'],
  ['人一作「民」，謀及卜筮。', '「人」有版本作「民」；要把事情和占卜一起謀議。'],
  ['汝則從、龜從、筮從、卿士從、庶民從，是之謂大同；', '如果你同意、龜卜同意、蓍草占筮同意、卿士同意、百姓也同意，這就叫大同；'],
  ['身其康彊，子孫其逢[9]：吉。', '自身會健康強壯，子孫也會遇到福運，這是吉兆；句末有校注編號九。'],
  ['汝則從、龜從、筮從、卿士逆、庶民逆：吉。', '如果你同意、龜卜和蓍筮同意，但卿士和百姓反對，仍然是吉兆。'],
  ['卿士從、龜從、筮從、汝則逆、庶民逆：吉。', '如果卿士、龜卜和蓍筮同意，但你和百姓反對，仍然是吉兆。'],
  ['庶民從、龜從、筮從、汝則逆、卿士逆：吉。', '如果百姓、龜卜和蓍筮同意，但你和卿士反對，仍然是吉兆。'],
  ['汝則從、龜從、筮逆、卿士逆、庶民逆：作內，吉；', '如果你和龜卜同意，但蓍筮、卿士、百姓反對，在國內行動是吉利的；'],
  ['作外，兇。', '對外行動則凶。'],
  ['龜筮共違於人：用靜，吉；', '如果龜卜和蓍筮都與人的意見相反，保持不動是吉利的；'],
  ['用作，兇。', '採取行動則凶。'],
  ['者一作「是、氏、韙」來備，各以其敘，庶', '「者」有版本作「是」「氏」或「韙」；各種徵候依次具備，百姓就會'],
  ['草一作「屮、卉」', '「草」有版本作「屮」或「卉」。'],
  ['蕃一作「緐」廡（蕪）。', '「蕃」有版本作「緐」；草木繁茂。'],
  ['一極備兇，一極無兇。', '如果某一種徵候完全出現，就會凶；另一種完全不出現，反而沒有凶象。'],
  ['豫一作「荼」（舒），恆燠若；', '「豫」有版本作「荼」或「舒」；長期溫暖和順；'],
  ['雺一作「蒙、霧、霿、瞀」，恆風若。', '「雺」有版本作「蒙」「霧」「霿」或「瞀」；長期多風也是如此。'],
  ['歲月日時無易，百穀用成，乂用明[11]，', '年、月、日、時節不失常序，百穀便能成熟，政治也會清明；句末有校注編號十一。'],
  ['俊一作「畯」民用章，家用平康。', '賢能的人使百姓的功業彰顯，家家都得到平安康樂；「俊」有版本作「畯」。'],
  ['日月歲時既易，百穀用不成，乂用昏不明，俊民用微，家用不寧。', '如果日月和四時失常，百穀就不能成熟，政治昏暗不明，賢能的人被埋沒，百姓家庭也不得安寧。'],
  ['庶民惟星，星有好[12]風，星有好雨[13]。', '百姓如同星辰；星辰各有順應的風和雨。此句附有校注編號十二、十三。'],
  ['日月之行，則有冬有夏；', '日月運行，因此有冬季和夏季；'],
  ['月之從星，則以風雨。', '月亮運行經過不同星宿，就會帶來風雨。'],
  ['↑《詩經·小雅·小旻》「國雖靡止，或聖或否，民雖靡膴，或哲或謀，或肅或艾」可參。', '校注引《詩經·小雅·小旻》作參考：「國家雖然不安定，有人聖明、有人昏暗；百姓雖然不富足，有人明智、有人善謀，有人嚴肅、有人能治。」'],
  ['↑「五紀」，見於清華簡《五紀》', '校注指出，「五紀」一詞也見於清華簡《五紀》。'],
  ['↑𬋝公盨（《銘圖》5677）「成父母，生我王」可參。', '校注引用𬋝公盨銘文「成父母，生我王」作比較。'],
  ['↑《左傳·桓公十一年》：「卜以決疑，不疑何卜。', '校注引《左傳·桓公十一年》說，占卜是用來解決疑惑；沒有疑惑，又何必占卜？'],
  ['晦猶終也。', '「晦」字有終結的意思。'],
  ['」《說文》：「𠧩，易卦之上體也。', '《說文解字》說：「𠧩，是易卦的上體。」'],
  ['↑《宋世家》作「凡七卜，五佔之用，二衍貣」。', '校注指出，《宋世家》作「凡七卜，五佔之用，二衍貣」。'],
  ['』則王仲任以『七卜』二字連讀，當讀『凡七卜（句）五佔之用（句）二衍貣（句）』史公與王仲任皆用歐陽《尚書》，其說多同，則《史記》亦當以『七卜』連讀。', '校注說王仲任把「七卜」連讀，應讀成「凡七卜、五佔之用、二衍貣」三句；司馬遷和王仲任都採用歐陽氏《尚書》，說法多相同，所以《史記》也應把「七卜」連讀。'],
  ['鄭雲『卜五，佔之用』，句讀稍異。', '鄭玄說應讀作「卜五，佔之用」，斷句略有不同。'],
  ['」（《今文尚書考證》第264頁）茲從今文說句讀。', '《今文尚書考證》採用今文《尚書》的斷句方式。'],
  ['』」', '（校注引文結束。）'],
  ['（《經義述聞（一）》第198—199頁）其說是，《易·大有》九四「匪其彭」之「彭」與「逢」通，殆亦應訓「大」', '《經義述聞》認為，《易經·大有》九四的「彭」與「逢」相通，這裡大概也應解釋為「大」。'],
  ['↑叔多父盤（《銘圖》14532、14533）銘雲「利於闢王、卿事、師尹」，次第正合。', '校注引用叔多父盤銘文，指出其中「闢王、卿事、師尹」的次序正好相合。'],
  ['（參劉起釪《〈洪範〉這篇統治大法的形成過程》、李學勤《叔多父盤與〈洪範〉》）', '校注建議參考劉起釪、李學勤關於《洪範》形成及叔多父盤的研究。'],
  ['↑樊毅修華嶽廟碑「艾用昭明」、鮮於璜碑「艾用照明」可參。', '校注引用樊毅修華嶽廟碑和鮮於璜碑的文字，作為「艾用昭明」的比較材料。'],
  ['」「好」字，柯劭忞雲：「好，畜之假字。', '校注說，「好」字是「畜」的通假字。'],
  ['《祭統》：『順於道，不過於倫，謂之畜。', '《祭統》說：「順從道理而不超越倫理，就叫作畜。」'],
  ['』是畜有從順義。', '因此「畜」有順從的意思。'],
  ['好風、好雨，言從風、從雨，非嗜好之好。', '「好風、好雨」是說順應風、順應雨，不是喜好的「好」。'],
  ['」（《尚書故》第151頁引）', '這段引文見於《尚書故》第151頁。'],
  ['↑《詩經·小雅·漸漸之石》：「月離於畢，俾滂沱矣。', '校注引用《詩經·小雅·漸漸之石》：「月亮經過畢宿，就會使雨勢滂沱。」'],
  ['」（「離」字之義參蔣文《先秦秦漢出土文獻與〈詩經〉文本的校勘和解讀》，復旦大學博士學位論文（指導教師：陳劍教授），2016年6月，第97—103頁）', '校注指出「離」字的意義可參考蔣文相關博士論文第97至103頁。'],
  ['↑𦅫鎛（《集成》271）「用求丂（考）命彌生」可參。', '校注引用𦅫鎛銘文「用求考命彌生」作比較。'],
  ['（《顧頡剛全集·顧頡剛讀書筆記（卷五）》「考終命」條，北京：中華書局，2011年，第483頁）', '校注引顧頡剛讀書筆記中「考終命」條，見中華書局2011年版第483頁。'],
  ['↑《康誥》「爽惟天其罰殛我，我其不怨」可參', '校注建議參考《康誥》中「上天若懲罰我，我也不怨恨」的句子。'],
  ['西旅厎貢厥獒。', '西方的旅國進獻了他們的大獒犬。'],
  ['明王慎德，四夷鹹賓。', '賢明的君王慎重修養德行，四方夷族都來朝見。'],
  ['無有遠邇，畢獻方物，惟服食器用。', '不論遠近，各地都獻上本地物產，只取可以穿戴、食用和使用的物品。'],
  ['分寶玉於伯叔之國，時庸展親。', '把珍寶玉器分賜給伯叔的封國，藉此真正表明親親之情。'],
  ['人不易物，惟德其物。', '不要因人而改變對物品的評價，真正可貴的是德行。'],
  ['德盛不狎侮；', '德行盛大的人不輕慢侮辱別人；'],
  ['狎侮君子，罔以盡人心；', '輕慢君子，就無法得到人心；'],
  ['狎侮小人，罔以盡其力。', '輕慢地位低下的人，就無法發揮他們的力量。'],
  ['不役耳目，百度惟貞，玩人喪德，玩物喪志。', '不要被聲色牽制，讓各種制度保持正直；戲弄人會喪失德行，玩弄器物會喪失志向。'],
  ['志以道寧，言以道接。', '志向依循正道就能安定，言語依循正道就能與人相接。'],
  ['犬馬非其土性不畜；', '不是本地土性所宜的犬馬，不要蓄養；'],
  ['珍禽奇獸，不育於國。', '珍奇禽獸，不要養在國中。'],
  ['不寶遠物，則遠人格；', '不把遠方的物品當寶物，遠方的人就會歸附；'],
  ['所寶惟賢，則邇人安。', '所珍視的只有賢人，身邊的人就會安定。'],
  ['夙夜罔或不勤，不矜細行，終累大德；', '早晚都不可不勤勉；不要以為小節無關緊要，最後會連累大德。'],
  ['既克商二年，王有疾，弗豫。', '攻克商朝後第二年，武王生病，病情不安。'],
  ['若爾三王，是有丕子之責於天，以旦代某之身。', '如果你們三位先王在天上，現在有重大的兒子責任要承擔，就讓我周公旦代替武王承受。'],
  ['予仁（年）若考，能多材多藝，能事鬼神。', '我年紀還輕，像父親一樣能多才多藝，也能敬事鬼神。'],
  ['無墜天之降寶命，我先王亦永有依歸。', '不要使上天降下的珍貴命令墜落，我們先王也能永遠有所依歸。'],
  ['今我即命於元龜，爾之許我，我其以璧與珪，歸俟爾命；', '現在我就向大龜占問天命；如果你們答應我，我便拿著璧和珪回去，等待你們的命令；'],
  ['予小子新（親）命於三王，惟永終是圖，茲攸俟，能念予一人。', '我這個小子親自向三位先王請命，只求謀劃長久的結局；如今等待你們的，就是能否顧念我一人。'],
  ['」周公居東二年，則罪人斯得於後。', '周公留在東方兩年後，叛亂的罪人終於被捕獲。'],
  ['王亦未敢誚〈逆〉公。', '成王也不敢責怪周公。'],
  ['秋大熟，未穫，天大雷電以風，禾盡偃，大木斯拔，邦人大恐。', '秋天莊稼大熟但還沒有收割時，天空突然雷電交加、颳起大風，禾苗全倒了，大樹也被拔起，國人都非常害怕。'],
  ['噫（抑）公命我勿敢言。', '唉！這大概是周公命令我不敢說出的事。'],
  ['昔公勤勞王家，惟予沖人弗及知；', '從前周公辛勞經營王室，只是我年幼，來不及知道這些事；'],
  ['今天動威，以彰周公之德；', '今天上天發動威勢，是要彰顯周公的德行；'],
  ['惟朕小子其新（親）逆，我國家禮亦宜之。', '我這個小子應當親自迎接周公，這也符合我國家的禮制。'],
  ['二公命邦人，凡大木所偃，盡起而築之，歲則大熟。', '召公、畢公命令國人，把所有被風吹倒的大樹扶起來培土，當年收成便大豐。'],
  ['（武王有疾，周公祝禱）武王既克殷三年，王不豫有遲。', '武王攻克殷朝後第三年，武王病情不安而拖延不癒。'],
  ['惟爾元孫發也，不若旦也，是佞若巧能，多才多藝，能事鬼神。', '你們的長孫姬發不如我周公旦，我善於應對和辦事，多才多藝，也能敬事鬼神。'],
  ['命於帝廷，溥有四方，以定爾子孫於下地。', '我在上帝的朝廷接受命令，要使四方廣大安定，讓你們的子孫在天下立足。'],
  ['爾之許我，我則瘞璧與珪。', '如果你們答應我，我就把璧和珪埋在地下作為祭祀。'],
  ['（天現異象，成王悔悟迎周公）是歲也，秋大熟，未刈。', '這一年秋天莊稼大熟，卻還沒有收割；這段記載天象異常，說明成王開始悔悟並準備迎回周公。'],
  ['天疾風以雷，禾斯偃，大木斯拔。', '天上颳起猛烈的風並伴隨雷聲，禾苗倒伏，大樹被拔起。'],
  ['邦人[皆/大恐。', '國人都非常害怕；此處原文有校訂異文。'],
  ['王口]弁，大夫綴[1]，以啓金縢之匱。', '成王戴著皮弁，大夫們跟隨在旁，於是打開金縢匱。'],
  ['噫，公命我勿敢言。', '唉，周公曾命令我不敢說出這件事。'],
  ['今皇天動威，以章公德。', '如今上天發動威勢，是為了彰顯周公的德行。'],
  ['_惟餘沖人其親逆公，我邦家禮亦宜之。', '我這個年幼的人應當親自迎接周公，這也符合我國家的禮制。'],
  ['是夕，天反風，禾斯起，凡大木之所拔，二公命邦人盡復築之。', '當天晚上，風向反轉，倒伏的禾苗重新立起；凡是被拔起的大樹，召公、畢公都命國人重新扶起培土。'],
  ['_歲大有年，秋則大刈。', '這一年大豐收，秋天收割了大量莊稼。'],
  ['後來方便今人閲讀，而加入標點符號的版權狀況可能是：', '以下是為方便今日讀者閱讀而加入標點的版權說明：'],
  ['若由維基文庫用戶自己的方式加入標點符號，依據知識共享署名-相同方式共享4.0協議（CCBY-SA4.0）及GNU自由文檔許可證（GFDL）的條款釋出。', '若標點由維基文庫使用者自行加入，依知識共享署名—相同方式共享4.0協議及GNU自由文件許可證的條款發布。'],
  ['此處民法通則的公平和等價有償原則與著作權是分別的話題。', '此處所說的民法公平、等價有償原則，和著作權問題是不同的議題。'],
  ['由人工智慧（AI）自動添加的標點符號。', '這些標點符號由人工智慧自動加入。'],
  ['其他國家或地區的法律規定可能有所不同，應依其適用法律判斷。', '其他國家或地區的法律可能不同，應依適用的法律判斷。'],
  ['參見：[1][2]。', '請參考注釋一、二。'],
  ['另請參見：章忠信《著作權筆記·句讀的著作權保護》', '另可參考章忠信《著作權筆記·句讀的著作權保護》。'],
  ['作者：姬旦', '作者：姬旦。'],
  ['弗弔（淑）！', '不要悲傷！「弔」有版本作「淑」。'],
  ['天降割（害）於我家，不少延。', '上天把禍害降到我家，沒有稍微延緩。'],
  ['洪〈引—矧〉惟我幼沖人，嗣無疆大歷服。', '我這個年幼的人承繼無邊的大業；「洪」等字有校訂異文。'],
  ['已（嘻）！', '唉！這個字有「嘻」的異文。'],
  ['予惟小子，若涉淵水，予惟往求朕攸濟。', '我這個小子就像要渡過深水，只能前去尋找可以渡過去的地方。'],
  ['敷賁，敷前人受命，茲不忘（亡）大功，予不敢閉於天降威。', '我廣泛承繼前人所受的天命，不敢忘記先人的大功，也不敢忽視上天降下的威勢。'],
  ['天降威，知我國有疵，民不康。', '上天降下威勢，知道我國有過失，百姓不得安寧。'],
  ['反鄙我周邦。', '反而輕視我們周國。'],
  ['今蠢（春）今翼（翌）日，民獻有十夫，予翼（異）以於敉〈—纂〉寧〈文〉武圖功。', '今天或說明天，百姓獻上十名賢人，我要依靠他們來安定、繼承文王武王的功業；其中多字有校訂異文。'],
  ['我有大事，休，朕卜並吉？', '我有重大事情要做，這是吉祥的事嗎？我的占卜結果是否都吉利？'],
  ['）不可徵；', '不能加以征討；'],
  ['王害不違卜？', '大王為什麼要害怕不遵從占卜呢？'],
  ['』肆予沖人永思艱。', '所以我這個年幼的人長久思考其中的艱難。'],
  ['允蠢鰥寡，哀哉！', '真正可憐的是孤苦無依的人，令人悲哀啊！'],
  ['予造（遭）天役，遺大投艱於朕身，越予沖人，不卬自恤。', '我遭逢上天交付的使命，巨大的艱難降到我身上；我這個年幼的人，不能只顧自己憂愁。'],
  ['』已（嘻）！', '唉！這個字有「嘻」的異文。'],
  ['予惟小子，不敢替〈朁—僭〉上帝命。', '我這個小子不敢僭越、改易上帝的命令。'],
  ['天休於寧〈文〉王，興我小邦周；', '上天降福給文王，使我們弱小的周國興起。'],
  ['寧〈文〉王惟卜用，克綏受茲命。', '文王依靠占卜，終能安定地承受這個天命。'],
  ['今天其相民，矧亦惟卜用。', '如今上天大概正在輔助百姓，何況我們又依靠占卜呢？'],
  ['天明畏（威），弼我丕丕基。', '上天明白而有威嚴，輔助我建立偉大的基業。'],
  ['肆予大化誘我友邦君，天棐（非）忱辭，其考我民，予曷其不於前寧人圖功攸終？', '所以我廣泛教導、引導友邦諸侯；上天不會只聽虛假的言辭，既然考察我們百姓，我怎能不替先王謀求完成大功呢？'],
  ['天亦惟用勤毖我民，若有疾，予曷敢不於前寧〈文〉人攸受休畢〈異—翼〉？', '上天也是用艱苦來勤勉警戒百姓，就像疾病一樣；我怎敢不完成從先王文王那裡承受的福命？'],
  ['』肆予曷敢不越卬敉〈—纂〉寧〈文〉王大命？', '所以我怎敢不超越自己，完成文王的大命？'],
  ['）其勸弗救？', '難道還能勸阻而不救助嗎？'],
  ['肆哉，爾庶邦君越爾御事，爽（相）邦由哲，亦惟十人，迪知上帝命越天棐（非）忱。', '所以，各位諸侯和你們的執事，要以明智輔助國家；那十位賢臣也都明白上帝的命令和上天不虛假的意志。'],
  ['爾時罔敢易法（廢），矧今天降戾於周邦？', '你們那時不敢改易法度，何況如今上天把禍患降給周國呢？'],
  ['爾亦不知天命不易。', '你們也應知道天命不會輕易改變。'],
  ['若穡夫，予曷敢不終朕畝？', '我就像耕種的人，怎敢不完成自己的田畝呢？'],
  ['天亦惟休於前寧〈文〉人，予曷其極卜？', '上天也曾降福給先王文王，我怎能把這件事推給占卜的極限呢？'],
  ['敢弗於從，率寧〈文〉人有指疆土？', '我難道敢不遵從，率領文王所指示的疆土嗎？'],
  ['矧今卜並吉？', '何況如今占卜結果全都吉利呢？'],
  ['肆朕誕以爾東徵；', '所以我大膽率領你們向東征伐；'],
  ['天命不僭，卜陳惟若茲。', '天命沒有差錯，占卜陳示的結果也是如此。'],
  ['殷王元子！', '殷王的長子啊！'],
  ['惟稽古，崇德象賢。', '要考察古代，尊崇德行，效法賢人。'],
  ['統承先王，修其禮物。', '承繼先王的統緒，修治禮制和禮器。'],
  ['三人行浴，見玄鳥墮其卵，簡狄取吞之，因孕生契。', '有三名女子一起到河邊沐浴，看見玄鳥落下一枚卵，簡狄取來吞下，因而懷孕生下契。'],
  ['契長而佐禹治水有功。', '契長大後輔佐禹治理洪水，立下功勞。'],
  ['」封於商，賜姓子氏。', '舜把契封在商地，賜給他子姓。'],
  ['契興於唐、虞、大禹之際，功業著於百姓，百姓以平。', '契在唐堯、虞舜和大禹的時代興起，功業受到百姓稱道，百姓因此得到安定。'],
  ['成湯，自契至湯八遷。', '成湯在位時，從契到成湯這一支商族曾經八次遷徙。'],
  ['湯始居亳，從先王居，作帝誥。', '商湯開始居住在亳地，沿用先王的居所，撰作《帝誥》。'],
  ['湯徵諸侯。', '商湯征伐並召集諸侯。'],
  ['勉哉，勉哉！', '努力啊，努力啊！'],
  ['」作湯徵。', '於是撰作《湯徵》。'],
  ['伊尹名阿衡。', '伊尹的官名叫阿衡。'],
  ['湯舉任以國政。', '商湯提拔伊尹，讓他主持國政。'],
  ['伊尹去湯適夏。', '伊尹離開商湯，前往夏朝。'],
  ['既醜有夏，復歸於亳。', '他看清夏朝的弊病後，又回到亳地。'],
  ['入自北門，遇女鳩、女房，作女鳩女房。', '伊尹從北門進入亳都，遇見女鳩和女房，於是撰作《女鳩》和《女房》。'],
  ['欲右，右。', '想向右邊走，便向右邊走。'],
  ['匪臺小子，敢行舉亂，有夏多罪，予維聞女眾言，夏氏有罪。', '不是我這個小子敢於擅自發動叛亂，而是夏朝罪行太多；我聽見你們眾人的話，知道夏氏確實有罪。'],
  ['予畏上帝，不敢不正。', '我敬畏上帝，不敢不討伐夏桀、匡正天下。'],
  ['今夏多罪，天命殛之。', '如今夏朝罪行眾多，上天命令我誅討它。'],
  ['夏王率止眾力，率奪夏國。', '夏王糾集眾人的力量，卻把夏國的權力奪在自己手中。'],
  ['予與女皆亡』！', '我和你們都會一起滅亡！」'],
  ['夏德若茲，今朕必往。', '夏朝的德行已經敗壞到這種地步，現在我一定要出兵。'],
  ['爾尚及予一人致天之罰，予其大理女。', '你們要和我一起執行上天的懲罰，我將重重賞賜你們。'],
  ['女毋不信，朕不食言。', '你們不要不相信，我不會食言。'],
  ['女不從誓言，予則帑僇女，無有攸赦。', '你們若不遵守誓言，我就把你們的妻子兒女一起殺戮，絕不赦免。']
  ,['」以告令師，作湯誓。', '商湯把這些話告訴並命令軍隊，撰作《湯誓》。']
  ,['桀敗於有娀之虛，桀犇於鳴條，夏師敗績。', '夏桀在有娀的故地戰敗，逃到鳴條，夏軍大敗。']
  ,['湯既勝夏，欲遷其社，不可，作夏社。', '商湯擊敗夏朝後，想遷移夏的社神，卻沒有這樣做，於是撰作《夏社》。']
  ,['伊尹報。', '伊尹作了答報。']
  ,['湯歸至於泰卷陶，中𤳹作誥。', '商湯回師到達泰卷陶，中𤳹撰作誥文。']
  ,['既絀夏命，還亳，作湯誥：「維三月，王自至於東郊。', '夏朝的天命既已被排除，商湯回到亳地，撰作《湯誥》：「三月，王親自到達東郊。']
  ,['告諸侯羣後：『毋不有功於民，勤力迺事。', '告訴諸侯和各地君長：『不可不為百姓建立功勞，要勤力辦理政事。']
  ,['后稷降播，農殖百穀。', '后稷教導百姓播種，農人因此種植各種穀物。']
  ,['先王言不可不勉。', '先王的教誡不可不努力遵行。』」']
  ,['伊尹作鹹有一德，咎單作明居。', '伊尹撰作《鹹有一德》，咎單撰作《明居》。']
  ,['帝太甲元年，伊尹作伊訓，作肆命，作徂後。', '太甲元年，伊尹撰作《伊訓》、《肆命》和《徂後》。']
  ,['三年，伊尹攝行政當國，以朝諸侯。', '太甲三年，伊尹代理政務主持國家，讓諸侯前來朝見。']
  ,['帝太甲居桐宮三年，悔過自責，反善，於是伊尹迺迎帝太甲而授之政。', '太甲在桐宮住了三年，悔恨過錯並自我責備，重新向善；伊尹於是迎接太甲回朝，把政權交還給他。']
  ,['帝太甲修德，諸侯鹹歸殷，百姓以寧。', '太甲修養德行，諸侯都歸附殷朝，百姓因此安寧。']
  ,['伊尹嘉之，迺作太甲訓三篇，襃帝太甲，稱太宗。', '伊尹嘉許太甲，於是撰作三篇《太甲訓》，褒揚太甲，稱他為太宗。']
  ,['殷道衰，諸侯或不至。', '殷朝的治道衰落，諸侯有些不再前來朝見。']
  ,['亳有祥，桑穀共生於朝，一暮大拱。', '亳地出現祥異，桑樹和穀樹一同生在朝廷中，一夜之間就長到兩手合抱那麼粗。']
  ,['帝太戊懼，問伊陟。', '太戊害怕，詢問伊陟。'],
  ['帝其修德。', '太戊應當修養德行。'],
  ['」太戊從之，而祥桑枯死而去。', '太戊照做後，祥異的桑樹便枯死消失了。']
  ,['伊陟贊言於巫咸。', '伊陟向巫咸進言。']
  ,['巫咸治王家有成，作鹹艾，作太戊。', '巫咸治理王室有成效，於是撰作《鹹艾》和《太戊》。']
  ,['帝太戊贊伊陟於廟，言弗臣，伊陟讓，作原命。', '太戊在宗廟稱揚伊陟，說不應把他當普通臣下；伊陟謙讓，於是撰作《原命》。']
  ,['殷復興，諸侯歸之，故稱中宗。', '殷朝重新興盛，諸侯都歸附，因此太戊被稱為中宗。']
  ,['帝中丁遷於隞，河亶甲居相，祖乙遷於邢。', '中丁遷都到隞，河亶甲居住在相，祖乙遷都到邢。']
  ,['仲丁書闕不具。', '仲丁的事蹟記載殘缺不全。']
  ,['河亶甲時，殷復衰。', '河亶甲時期，殷朝再次衰落。']
  ,['巫賢任職。', '巫賢擔任官職。']
  ,['帝陽甲之時，殷衰。', '陽甲時期，殷朝衰落。']
  ,['帝盤庚之時，殷已都河北，盤庚渡河南，復居成湯之故居，迺五遷，無定處。', '盤庚時，殷朝已經建都在黃河北岸；盤庚渡過黃河向南，重新住在成湯的故都，前後已經五次遷都，沒有固定的居所。']
  ,['殷民諮胥皆怨，不欲徙。', '殷民彼此怨恨，都不想遷徙。']
  ,['舍而弗勉，何以成德！', '如果捨棄努力，怎麼能成就德行呢！']
  ,['諸侯來朝，以其遵成湯之德也。', '諸侯前來朝見，因為盤庚遵循成湯的德政。']
  ,['百姓思盤庚，迺作盤庚三篇。', '百姓思念盤庚，於是撰作三篇《盤庚》。']
  ,['帝武丁即位，思復興殷，而未得其佐。', '武丁即位後，想讓殷朝復興，卻還沒有找到輔佐他的人。']
  ,['三年不言，政事決定於冢宰，以觀國風。', '武丁即位後三年不說話，把政事交給冢宰決定，以觀察國家的情勢。']
  ,['以夢所見視羣臣百吏，皆非也。', '他把夢中見到的形貌拿來比對群臣百官，卻都不是那個人。']
  ,['於是迺使百工營求之野，得說於傅險中。', '於是派百官到野外尋找，終於在傅險找到說。']
  ,['帝武丁祭成湯，明日，有飛雉登鼎耳而呴，武丁懼。', '武丁祭祀成湯的第二天，有飛來的雉鳥站在鼎耳上鳴叫，武丁感到害怕。']
  ,['鳴呼！', '唉！']
  ,['王嗣敬民，罔非天繼，常祀毋禮於棄道。', '君王繼承王位後要敬愛百姓，沒有一件事不是承接上天的命令；日常祭祀不可怠慢，也不可走上被上天拋棄的道路。']
  ,['」武丁修政行德，天下鹹驩，殷道復興。', '武丁整頓政事、施行德政，天下都感到歡喜，殷朝的治道重新興盛。']
  ,['帝甲淫亂，殷復衰。', '帝甲荒淫昏亂，殷朝再次衰落。']
  ,['殷復去亳，徙河北。', '殷朝又離開亳地，遷都到黃河北岸。']
  ,['武乙獵於河渭之閒，暴雷，武乙震死。', '武乙在黃河、渭水之間打獵時突然雷暴，被雷震死。'],
  ['帝紂資辨捷疾，聞見甚敏；', '紂王天資聰敏、反應迅速，見聞十分敏銳。'],
  ['材力過人，手格猛獸；', '他的才力超過常人，徒手就能搏擊猛獸。'],
  ['知足以距諫，言足以飾非；', '他的智力足以拒絕諫言，口才足以掩飾錯誤。'],
  ['好酒淫樂，嬖於婦人。', '他沉溺酒色和淫靡享樂，尤其寵愛婦人。'],
  ['愛妲己，妲己之言是從。', '他寵愛妲己，凡是妲己說的話都照做。'],
  ['於是使師涓作新淫聲，北里之舞，靡靡之樂。', '於是命師涓創作新的淫靡樂曲，編排北里的舞蹈，製造使人沉溺的音樂。'],
  ['厚賦稅以實鹿臺之錢，而盈鉅橋之粟。', '他加重賦稅，充實鹿臺的錢庫，又把鉅橋的糧倉堆滿。'],
  ['益收狗馬奇物，充仞宮室。', '他更加搜羅犬馬和奇珍異物，把宮室塞得滿滿的。'],
  ['益廣沙丘苑臺，多取野獸蜚鳥置其中。', '他不斷擴大沙丘的苑囿和高臺，捕捉大量野獸飛鳥放在其中。'],
  ['慢於鬼神。', '他怠慢、輕侮鬼神。'],
  ['九侯有好女，入之紂。', '九侯有一個美麗的女兒，把她送進紂王的後宮。'],
  ['九侯女不憙淫，紂怒，殺之，而醢九侯。', '九侯的女兒不喜歡淫靡之事，紂王大怒，殺死她，又把九侯剁成肉醬。'],
  ['鄂侯爭之彊，辨之疾，並脯鄂侯。', '鄂侯強烈爭辯，言辭急切，紂王便把鄂侯也殺死，製成肉乾。'],
  ['西伯昌聞之，竊嘆。', '西伯姬昌聽見這件事，私下嘆息。'],
  ['崇侯虎知之，以告紂，紂囚西伯羑里。', '崇侯虎知道後告訴紂王，紂王便把西伯囚禁在羑里。'],
  ['西伯出而獻洛西之地，以請除炮格之刑。', '西伯獲釋後，獻出洛水以西的土地，請求紂王廢除炮格刑。'],
  ['費中善諛，好利，殷人弗親。', '費中善於諂媚，又貪圖財利，殷人都不親近他。'],
  ['紂又用惡來。', '紂王又任用惡來。'],
  ['惡來善毀讒，諸侯以此益疏。', '惡來善於詆毀和進讒言，諸侯因此更加疏遠殷朝。'],
  ['西伯滋大，紂由是稍失權重。', '西伯的勢力日益壯大，紂王因此逐漸失去權勢和威望。'],
  ['王子比干諫，弗聽。', '王子比干進諫，紂王不肯聽。'],
  ['商容賢者，百姓愛之，紂廢之。', '商容是賢能的人，百姓愛戴他，紂王卻罷免了他。'],
  ['今王其柰何？', '如今大王要怎麼辦呢？'],
  ['紂愈淫亂不止。', '紂王更加淫亂，始終沒有停止。'],
  ['」迺強諫紂。', '於是比干強烈勸諫紂王。'],
  ['」剖比干，觀其心。', '紂王剖開比干的胸腹，觀看他的心。'],
  ['紂亦發兵距之牧野。', '紂王也派兵在牧野抵抗周軍。'],
  ['甲子日，紂兵敗。', '甲子日，紂軍戰敗。'],
  ['紂走，入登鹿臺，衣其寶玉衣，赴火而死。', '紂王逃走，登上鹿臺，穿著寶玉製成的衣服，投火自焚而死。'],
  ['殺妲己。', '武王殺死妲己。'],
  ['釋箕子之囚，封比干之墓，表商容之閭。', '武王釋放被囚的箕子，修整比干的墓，在商容的里門立表彰他的牌坊。'],
  ['封紂子武庚祿父，以續殷祀，令修行盤庚之政。', '武王封紂王的兒子武庚祿父，讓他延續殷的祭祀，並命他奉行盤庚的政令。'],
  ['殷民大說。', '殷地百姓非常喜悅。'],
  ['周后稷，名棄。', '周人的始祖后稷，名字叫棄。'],
  ['姜原出野，見巨人跡，心忻然說，欲踐之，踐之而身動如孕者。', '姜原到野外，看見巨人的腳印，心中歡喜，想踩上去；踩過之後身體悸動，就像懷孕了一樣。'],
  ['徙置之林中，適會山林多人，遷之；', '她把孩子搬到森林裡，恰好遇到山林中有很多人，便又把他移走；'],
  ['而棄渠中冰上，飛鳥以其翼覆薦之。', '又把他丟在水渠的冰上，飛鳥便用翅膀覆蓋、墊護他。'],
  ['其遊戲，好種樹麻、菽，麻、菽美。', '他玩耍時喜歡種植麻和豆，種出的麻豆都長得很好。'],
  ['后稷之興，在陶唐、虞、夏之際，皆有令德。', '后稷在陶唐、虞舜和夏朝之間興起，始終具有美好的德行。'],
  ['不窋末年，夏后氏政衰，去稷不務，不窋以失其官而犇戎狄之間。', '不窋晚年，夏后氏的政事衰敗，不再重視農官；不窋因失去官職而逃到戎狄之間。'],
  ['公劉雖在戎狄之間，復修后稷之業，務耕種，行地宜，自漆、沮度渭，取材用，行者有資，居者有畜積，民賴其慶。', '公劉雖然住在戎狄之間，仍重新修治后稷的事業，致力耕種，按照土地適宜之處開墾；他從漆水、沮水渡過渭水，取得木材等資源，使出行的人有資用，居住的人有積蓄，百姓都享受到他的福澤。'],
  ['百姓懷之，多徙而保歸焉。', '百姓懷念並依附他，許多人遷徙來歸附。'],
  ['周道之興自此始，故詩人歌樂思其德。', '周人道路的興盛從此開始，所以詩人歌唱歡樂，追念公劉的德行。'],
  ['古公亶父復修后稷、公劉之業，積德行義，國人皆戴之。', '古公亶父重新修治后稷、公劉的事業，累積德行、施行義政，國人都擁戴他。'],
  ['薰育戎狄攻之，欲得財物，予之。', '薰育的戎狄攻打古公，想得到財物，古公便給了他們。'],
  ['已復攻，欲得地與民。', '戎狄後來又來攻打，想取得土地和百姓。'],
  ['民皆怒，欲戰。', '百姓都很憤怒，想要出戰。'],
  ['民之在我，與其在彼，何異。', '百姓留在我這裡，和留在他們那裡有什麼不同呢？'],
  ['豳人舉國扶老攜弱，盡復歸古公於岐下。', '豳地人全國扶老攜幼，全部跟隨古公遷到岐山腳下。'],
  ['及他旁國聞古公仁，亦多歸之。', '附近其他國家聽說古公仁厚，也有許多人來歸附。'],
  ['作五官有司。', '古公設置五官和各種主管官職。'],
  ['民皆歌樂之，頌其德。', '百姓都歌唱讚美古公，頌揚他的德行。'],
  ['太姜生少子季歷，季歷娶太任，皆賢婦人，生昌，有聖瑞。', '太姜生下小兒子季歷；季歷娶太任為妻，兩人都是賢德的婦人，生下姬昌，並出現聖異的祥瑞。'],
  ['公季修古公遺道，篤於行義，諸侯順之。', '公季修治古公留下的道路，專心施行仁義，諸侯都順服他。'],
  ['禮下賢者，日中不暇食以待士，士以此多歸之。', '他以禮對待賢者，常常忙到中午也無暇吃飯來接待士人，士人因此多來歸附。'],
  ['伯夷、叔齊在孤竹，聞西伯善養老，盍往歸之。', '伯夷、叔齊在孤竹，聽說西伯善於奉養老人，便說：「何不前去歸附他呢？」'],
  ['太顛、閎夭、散宜生、鬻子、辛甲大夫之徒皆往歸之。', '太顛、閎夭、散宜生、鬻子、辛甲等大夫也都前往歸附西伯。'],
  ['閎夭之徒患之。', '閎夭等人為此感到憂慮。'],
  ['紂許之。', '紂王答應了。'],
  ['西伯陰行善，諸侯皆來決平。', '西伯暗中施行善政，諸侯遇到爭端都來請他裁決。'],
  ['入界，耕者皆讓畔，民俗皆讓長。', '進入周的境界後，耕田的人都互相讓出田界，民間風俗也都尊讓年長者。'],
  ['明年，敗耆國。', '第二年，西伯擊敗耆國。'],
  ['殷之祖伊聞之，懼，以告帝紂。', '殷的大臣祖伊聽到後很害怕，把這件事告訴紂王。'],
  ['而作豐邑，自岐下而徙都豐。', '西伯又營建豐邑，從岐山腳下遷都到豐地。'],
  ['西伯蓋即位五十年。', '西伯大概在位五十年。'],
  ['詩人道西伯，蓋受命之年稱王而斷虞芮之訟。', '詩人歌詠西伯，說他大概在接受天命的那一年稱王，並裁決了虞國、芮國的爭訟。'],
  ['改法度，制正朔矣。', '他改革法度，制定曆法和正朔。'],
  ['九年，武王上祭於畢。', '文王九年，武王在畢地舉行祭祀。'],
  ['東觀兵，至於盟津。', '周軍向東展示軍力，抵達盟津。'],
  ['』」以令諸侯。', '用這些話命令諸侯。'],
  ['使者已行矣。', '使者已經出發了。'],
  ['是善用兵，又有天命。', '白起很善於用兵，而且似乎又有天命相助。'],
  ['」武王乃作《太誓》，告於眾庶：「今殷王紂乃用其婦人之言，自絕於天，毀壞其三正，離逖其王父母弟，乃斷棄其先祖之樂，乃為淫聲，用變亂正聲，怡說婦人。', '武王於是撰作《太誓》，告訴眾人：「現在殷王紂只聽從婦人的話，自己斷絕了與上天的關係；毀壞三公的官制，疏遠王室的父兄弟弟；又拋棄先祖的樂舞，製作淫靡的聲音，以混亂正統的音樂，只討婦人的歡心。」'],
  ['」王曰：「古人有言『牝雞無晨。', '武王說：「古人有句話：『母雞不應在清晨啼叫。'],
  ['師尚父號曰：「總爾眾庶，與爾舟楫，後至者斬。', '太公望大聲命令：「集合你們眾人，帶上船隻；最後到達的人斬首。」'],
  ['」武王渡河，中流，白魚躍入王舟中，武王俯取以祭。', '武王渡河時，白魚從河中跳進王船，武王俯身把它取來祭祀。'],
  ['既渡，有火自上復於下，至於王屋，流為烏，其色赤，其聲魄雲。', '渡河後，有火從天而降，落到武王的屋上，化作赤色的烏鴉，發出魄雲般的聲音。'],
  ['是時，諸侯不期而會盟津者八百諸侯。', '當時，沒有事先約定，卻有八百諸侯在孟津會合。'],
  ['諸侯皆曰：「紂可伐矣。', '諸侯都說：「現在可以討伐紂王了。」'],
  ['」武王曰：「女未知天命，未可也。', '武王說：「你們還不知道天命，現在還不能出兵。」'],
  ['」乃還師歸。', '於是武王撤軍返回。'],
  ['居二年，聞紂昏亂暴虐滋甚，殺王子比干，囚箕子。', '過了兩年，武王聽說紂王更加昏庸暴虐，殺了王子比干，囚禁了箕子。'],
  ['太師疵、少師彊抱其樂器而奔周。', '太師疵和少師彊帶著樂器逃到周國。'],
  ['於是武王遍告諸侯曰：「殷有重罪，不可以不畢伐。', '武王於是遍告諸侯：「殷商罪行重大，不能不把它徹底討伐。」'],
  ['」乃遵文王，遂率戎車三百乘，虎賁三千人，甲士四萬五千人，以東伐紂。', '武王於是遵循文王的遺志，率領三百輛戰車、三千名虎賁武士和四萬五千名甲士，向東討伐紂王。'],
  ['十一年十二月戊午，師畢渡盟津，諸侯鹹會。', '周武王十一年十二月戊午日，周軍全部渡過孟津，諸侯也都來會合。'],
  ['曰：「孳孳無怠！', '眾人說：「勤勉不懈怠！」'],
  ['故今予發維共行天罰。', '所以現在我姬發要和諸侯一起執行上天的懲罰。'],
  ['勉哉夫子，不可再，不可三！', '努力吧，將士們；這次不能再三反覆、坐失時機！'],
  ['二月甲子昧爽，武王朝至於商郊牧野，乃誓。', '二月甲子日黎明，武王早晨抵達商都郊外的牧野，向軍隊宣誓。'],
  ['武王左杖黃鉞，右秉白旄，以麾。', '武王左手拿著黃金大斧，右手握著白色旄旗，用旗幟指揮軍隊。'],
  ['曰：「遠矣西土之人！', '武王說：「來自西方土地的將士們，你們辛苦遠行了！」'],
  ['」武王曰：「嗟！', '武王說：「唉！」'],
  ['我有國冢君，司徒、司馬、司空，亞旅、師氏，千夫長、百夫長，及庸、蜀、羌、髳、微、纑、彭、濮人，稱爾戈，比爾幹，立爾矛，予其誓。', '我的諸侯，以及司徒、司馬、司空、亞旅、師氏、千夫長、百夫長，還有庸、蜀、羌、髳、微、纑、彭、濮各地的人，舉起你們的戈，排列好盾牌，豎起你們的長矛，聽我宣誓。'],
  ['王曰：「古人有言『牝雞無晨。', '武王說：「古人有句話：『母雞不應在清晨啼叫。'],
  ['牝雞之晨，惟家之索』。', '母雞若在清晨啼叫，家道就會衰敗。』'],
  ['今殷王紂維婦人言是用，自棄其先祖肆祀不答，昏棄其家國，遺其王父母弟不用，乃維四方之多罪逋逃是崇是長，是信是使，俾暴虐於百姓，以姦軌於商國。', '現在殷王紂只聽從婦人的話，拋棄先祖、荒廢祭祀；昏亂地拋棄自己的家國，不任用王室的父兄弟弟，反而尊崇、重用四方逃亡的罪人，讓他們殘暴對待百姓，在商國製造奸邪與禍亂。'],
  ['今予發維共行天之罰。', '現在我姬發要和諸侯一起執行上天的懲罰。'],
  ['今日之事，不過六步七步，乃止齊焉，夫子勉哉！', '今天作戰時，前進六步、七步就停下來整隊；將士們，努力作戰吧！'],
  ['不過於四伐五伐六伐七伐，乃止齊焉，勉哉夫子！', '揮兵攻擊四次、五次、六次、七次就停下整隊；將士們，努力作戰吧！'],
  ['尚桓桓，如虎如羆，如豺如離，於商郊，不御克奔，以役西土，勉哉夫子！', '你們要勇猛威武，像虎、熊、豺狼一樣，在商都郊外作戰；不要阻攔已經逃跑的敵人，讓這場戰事完成西方諸侯的使命。將士們，努力吧！'],
  ['爾所不勉，其於爾身有戮。', '你們如果不盡力，就會受到殺戮的刑罰。」'],
  ['」誓已，諸侯兵會者車四千乘，陳師牧野。', '宣誓完畢，前來會師的諸侯共有四千輛戰車，軍隊在牧野列陣。'],
  ['帝紂聞武王來，亦發兵七十萬人距武王。', '紂王聽說武王到來，也派出七十萬軍隊抵抗武王。'],
  ['武王使師尚父與百夫致師，以大卒馳帝紂師。', '武王派太公望帶領一百名士兵挑戰紂軍，自己則率大軍向紂王的軍隊衝去。'],
  ['紂師雖眾，皆無戰之心，心欲武王亟入。', '紂軍人數雖多，卻都沒有作戰的意志，心裡希望武王趕快攻入。'],
  ['紂師皆倒兵以戰，以開武王。', '紂軍紛紛倒轉兵器表示投降，為武王讓開道路。'],
  ['武王馳之，紂兵皆崩畔紂。', '武王乘勢追擊，紂軍全部潰散，背叛了紂王。'],
  ['紂走，反入登於鹿臺之上，蒙衣其殊玉，自燔於火而死。', '紂王逃走，回到鹿臺，披上珍貴的玉衣，自己投火焚燒而死。'],
  ['武王持大白旗以麾諸侯，諸侯畢拜武王，武王乃揖諸侯，諸侯畢從。', '武王舉起大白旗向諸侯示意，諸侯都向武王行禮；武王也向諸侯作揖，諸侯於是全部跟隨他。'],
  ['武王至商國，商國百姓鹹待於郊。', '武王到達商都時，商地百姓都在郊外迎候。'],
  ['於是武王使羣臣告語商百姓曰：「上天降休！', '武王於是派群臣告訴商地百姓：「上天降下了福祐！」'],
  ['」商人皆再拜稽首，武王亦答拜。', '商地百姓都拜了兩拜並叩頭，武王也回拜答禮。'],
  ['遂入，至紂死所。', '武王於是進入城中，來到紂王自焚身亡的地方。'],
  ['武王自射之，三發而後下車，以輕劍擊之，以黃鉞斬紂頭，縣大白之旗。', '武王親自射了紂王三箭，然後下車，用短劍刺擊紂王，再用黃金大斧砍下紂王的頭，懸掛在大白旗上。'],
  ['已而至紂之嬖妾二女，二女皆經自殺。', '接著找到紂王寵愛的兩名女子，兩人都上吊自殺了。'],
  ['武王又射三發，擊以劍，斬以玄鉞，縣其頭小白之旗。', '武王又向她們各射三箭，再用劍刺擊，用黑色大斧砍下她們的頭，懸掛在小白旗上。'],
  ['武王已乃出復軍。', '武王處理完畢後，出城回到軍中。'],
  ['其明日，除道，修社及商紂宮。', '第二天，周人清理道路，整修土地神社和商紂的宮室。'],
  ['及期，百夫荷罕旗以先驅。', '到了祭告的日期，一百名士兵扛著大旗在前面開路。'],
  ['武王弟叔振鐸奉陳常車，周公旦把大鉞，畢公把小鉞，以夾武王。', '武王的弟弟叔振鐸捧著陳列禮器的車，周公旦手持大斧，畢公手持小斧，左右護衛武王。'],
  ['散宜生、太顛、閎夭皆執劍以衛武王。', '散宜生、太顛和閎夭都拿著劍護衛武王。'],
  ['既入，立於社南大卒之左，［左］右畢從。', '進入之後，武王站在社壇南面、軍隊左側的位置，左右侍從和群臣都跟隨在後。'],
  ['毛叔鄭奉明水，衛康叔封布茲，召公奭贊採，師尚父牽牲。', '毛叔鄭捧著清潔的祭水，衛康叔封鋪設坐席，召公奭協助主持儀式，太公望牽來祭牲。'],
  ['尹佚筴祝曰：「殷之末孫季紂，殄廢先王明德，侮蔑神祇不祀，昏暴商邑百姓，其章顯聞於天皇上帝。', '尹佚拿著祝冊祝告：「殷的末代君主帝辛，完全敗壞先王的明德，侮辱神祇而不祭祀，使商都百姓陷於昏亂暴虐；他的罪行已明白地被天皇上帝知悉。'],
  ['」於是武王再拜稽首，曰：「膺更大命，革殷，受天明命。', '武王於是拜了兩拜並叩頭，說：「我承受並更新上天的大命，革除殷的統治，接受上天明白的命令。'],
  ['武王又再拜稽首，乃出。', '武王又拜了兩拜並叩頭，才走出祭所。'],
  ['封商紂子祿父殷之餘民。', '武王封紂王的兒子祿父，讓他統治殷商的遺民。'],
  ['武王為殷初定未集，乃使其弟管叔鮮、蔡叔度相祿父治殷。', '武王認為殷地剛平定、秩序還沒有安定，便派弟弟管叔鮮和蔡叔度輔佐祿父治理殷地。'],
  ['已而命召公釋箕子之囚。', '不久，武王命召公釋放被囚禁的箕子。'],
  ['命畢公釋百姓之囚，表商容之閭。', '武王命畢公釋放被囚的百姓，並在商容的里門立表彰他的牌坊。'],
  ['命南宮括散鹿臺之財，發鉅橋之粟，以振貧弱萌隸。', '武王命南宮括散發鹿臺府庫的財物，開出鉅橋倉庫的糧食，用來救濟貧困、弱小和受役使的百姓。'],
  ['命南宮括、史佚展九鼎保玉。', '武王命南宮括和史佚檢視九鼎及珍貴的玉器，妥善保管。'],
  ['命閎夭封比干之墓。', '武王命閎夭修整並封土祭祀比干的墓。'],
  ['命宗祝享祠于軍。', '武王命宗官和祝官在軍中舉行祭祀。'],
  ['乃罷兵西歸。', '於是武王解散軍隊，向西返回周地。'],
  ['行狩，記政事，作《武成》。', '武王出外巡狩，記錄這次討伐的政事，撰作《武成》。'],
  ['封諸侯，班賜宗彝，作《分殷之器物》。', '武王分封諸侯，分賜宗廟祭器，撰作《分殷之器物》。'],
  ['武王追思先聖王，乃褒封神農之後於焦，黃帝之後於祝，帝堯之後於薊，帝舜之後於陳，大禹之後於杞。', '武王追念前代的聖王，於是尊崇分封神農的後代在焦地、黃帝的後代在祝地、帝堯的後代在薊地、帝舜的後代在陳地、大禹的後代在杞地。'],
  ['於是封功臣謀士，而師尚父為首封。', '武王於是分封功臣和謀士，太公望被列為首先受封的人。'],
  ['封尚父於營丘，曰齊。', '武王把營丘封給太公望，國號稱為齊。'],
  ['封弟周公旦於曲阜，曰魯。', '武王把曲阜封給弟弟周公旦，國號稱為魯。'],
  ['封召公奭於燕。', '武王把燕地封給召公奭。'],
  ['封弟叔鮮於管，弟叔度於蔡。', '武王把管地封給弟弟叔鮮，把蔡地封給弟弟叔度。'],
  ['餘各以次受封。', '其餘功臣和宗室也依照次序接受分封。'],
  ['武王徵九牧之君，登豳之阜，以望商邑。', '武王召集九州牧守的君長，登上豳地的高丘，遠望商都。'],
  ['武王至於周，自夜不寐。', '武王回到周地後，整夜都睡不著。'],
  ['周公旦即王所，曰：「曷為不寐？', '周公旦來到武王住處，問：「為什麼不睡呢？」'],
  ['」王曰：「告女：維天不饗殷，自發未生於今六十年，麋鹿在牧，蜚鴻滿野。', '武王說：「告訴你吧：上天已不再享用殷的祭祀。從我姬發尚未出生到現在已有六十年，原野牧地到處有麋鹿，野外充滿流離失所的人。'],
  ['天不享殷，乃今有成。', '正因上天不再護佑殷，今天我們才得以成功。'],
  ['維天建殷，其登名民三百六十夫，不顯亦不賓滅，以至今。', '當初上天建立殷朝，列入名冊的賢臣有三百六十人；他們雖然沒有受到顯揚，也沒有被賓客般尊奉，卻仍延續到今天。'],
  ['我未定天保，何暇寐！', '我還沒有使天下的安定局面確立，哪有空閒睡覺呢！」'],
  ['」王曰：「定天保，依天室，悉求夫惡，貶從殷王受。', '武王又說：「要確立天下的安定，就要依循上天的法則，全面查究那些罪惡之人，把他們降黜，讓他們承受殷王紂所造成的後果。'],
  ['日夜勞來定我西土，我維顯服，及德方明。', '我日夜辛勞，使西方土地安定；只要我明白履行職責，德行才會逐漸彰顯。」'],
  ['自洛汭延於伊汭，居易毋固，其有夏之居。', '從洛水彎曲處延伸到伊水彎曲處，居處要選擇平易之地，不要固守險要，這裡就是夏朝曾經建都的地方。'],
  ['我南望三塗，北望嶽鄙，顧詹有河，粵詹雒、伊，毋遠天室。', '我向南望三塗山，向北望嶽山一帶；回頭看見黃河，又看見洛水和伊水，這裡不要離天子宮室太遠。'],
  ['」營周居於雒邑而後去。', '武王在雒邑營建周人的居所，然後離開。'],
  ['縱馬於華山之陽，放牛於桃林之虛；', '把馬放牧在華山南面，把牛放養在桃林的空地。'],
  ['偃干戈，振兵釋旅：示天下不復用也。', '放下盾牌和武器，解散軍隊，向天下表示今後不再動用武力。'],
  ['武王已克殷，後二年，問箕子殷所以亡。', '武王攻克殷朝後第二年，詢問箕子殷朝滅亡的原因。'],
  ['箕子不忍言殷惡，以存亡國宜告。', '箕子不忍心直接說殷朝的罪惡，認為對亡國之君只能用保存體面的方式告訴他。'],
  ['武王亦醜，故問以天道。', '武王也覺得難以啟齒，所以改以天道來詢問。'],
  ['武王病。', '武王病重。'],
  ['天下未集，羣公懼，穆卜，周公乃祓齋，自為質，欲代武王，武王有瘳。', '天下還沒有安定，群臣都很害怕；他們恭敬地占卜，周公於是沐浴齋戒，願意以自己作為人質，代替武王承受禍患，武王的病因此好轉。'],
  ['後而崩，太子誦代立，是為成王。', '後來武王去世，太子姬誦繼位，這就是周成王。'],
  ['成王少，周初定天下，周公恐諸侯畔周，公乃攝行政當國。', '成王年幼，周朝剛平定天下，周公擔心諸侯背叛周室，便代理政務主持國政。'],
  ['管叔、蔡叔羣弟疑周公，與武庚作亂，畔周。', '管叔、蔡叔等成王的兄弟懷疑周公，便和武庚一起作亂，背叛周朝。'],
  ['周公奉成王命，伐誅武庚、管叔，放蔡叔。', '周公奉成王的命令出兵，誅殺武庚和管叔，流放蔡叔。'],
  ['以微子開代殷後，國於宋。', '周朝讓微子啟承接殷的後裔，在宋地建立國家。'],
  ['頗收殷餘民，以封武王少弟封為衛康叔。', '周公收編不少殷商遺民，並把武王的小弟封分封為衛國的康叔。'],
  ['晉唐叔得嘉穀，獻之成王，成王以歸周公於兵所。', '晉國的唐叔得到優良的穀物，獻給成王；成王把它轉交給正在軍中的周公。'],
  ['周公受禾東土，魯天子之命。', '周公接受東方土地獻來的禾穀，並把天子的命令帶回魯地。'],
  ['初，管、蔡畔周，周公討之，三年而畢定，故初作《大誥》，次作《微子之命》，次《歸禾》，次《嘉禾》，次《康誥》、《酒誥》、《梓材》，其事在周公之篇。', '起初管叔、蔡叔背叛周朝，周公出兵討伐，三年後才完全平定。因此先作《大誥》，接著作《微子之命》、《歸禾》、《嘉禾》、《康誥》、《酒誥》和《梓材》，相關事蹟都記載在周公篇章中。'],
  ['周公行政七年，成王長，周公反政成王，北面就羣臣之位。', '周公代理政務七年後，成王長大成人；周公把政權交還成王，自己面向北方回到群臣的位置。'],
  ['成王在豐，使召公復營洛邑，如武王之意。', '成王在豐地時，派召公重新營建洛邑，按照武王原來的意圖辦理。'],
  ['周公復卜申視，卒營築，居九鼎焉。', '周公再次占卜並仔細勘察，終於完成營建，把九鼎安置在那裡。'],
  ['曰：「此天下之中，四方入貢道里均。', '周公說：「這裡是天下的中心，四方來進貢的路程都大致相等。'],
  ['」作《召誥》、《洛誥》。', '於是撰作《召誥》和《洛誥》。'],
  ['成王既遷殷遺民，周公以王命告，作《多士》、《無佚》。', '成王把殷商遺民遷到新都後，周公奉成王的命令發布告誡，撰作《多士》和《無佚》。'],
  ['召公為保，周公為師，東伐淮夷，殘奄，遷其君薄泵。', '召公任太保，周公任太師；他們向東討伐淮夷，摧毀奄國，並把奄國君主遷到薄姑。'],
  ['成王自奄歸，在宗周，作《多方》。', '成王從奄地回到宗周，撰作《多方》。'],
  ['既絀殷命，襲淮夷，歸在豐，作《周官》。', '周朝既已排除殷商勢力，又出兵突襲淮夷；成王回到豐地後，撰作《周官》。'],
  ['興正禮樂，度制於是改，而民和睦，頌聲興。', '周朝振興並整頓禮樂，制度也因此改革，百姓和睦相處，歌頌太平的聲音興起。'],
  ['成王既伐東夷，息慎來賀，王賜榮伯作《賄息慎之命》。', '成王討伐東夷後，息慎前來祝賀；成王賞賜榮伯，命他撰作《賄息慎之命》。'],
  ['成王將崩，懼太子釗之不任，乃命召公、畢公率諸侯以相太子而立之。', '成王將要去世時，擔心太子釗不能勝任，便命召公和畢公率領諸侯輔佐太子，扶立他繼位。'],
  ['成王既崩，二公率諸侯，以太子釗見於先王廟，申告以文王、武王之所以為王業之不易，務在節儉，毋多欲，以篤信臨之，作《顧命》。', '成王去世後，召公、畢公率諸侯帶太子釗到先王宗廟，反覆告誡他：文王、武王建立王業十分艱難，治理國家務必節儉、不可多欲，並要以深厚的信德面對天下；這些話寫成《顧命》。'],
  ['太子釗遂立，是為康王。', '太子釗於是繼位，這就是周康王。'],
  ['康王即位，遍告諸侯，宣告以文武之業以申之，作《康誥》。', '康王即位後，遍告諸侯，宣示文王、武王的功業，重申先王的政道，撰作《康誥》。'],
  ['故成康之際，天下安寧，刑錯四十餘年不用。', '因此成王、康王時期天下安寧，刑具被擱置不用，四十多年沒有施用刑罰。'],
  ['康王命作策畢公分居里，成周郊，作《畢命》。', '康王命畢公撰寫策命，分別安置成周郊外各里的居民，並作《畢命》。'],
  ['康王卒，子昭王瑕立。', '康王去世，兒子瑕繼位，這就是周昭王。'],
  ['昭王之時，王道微缺。', '昭王在位時，王道開始衰微、制度也出現缺失。'],
  ['昭王南巡狩不返，卒於江上。', '昭王南下巡狩後沒有回來，死在江邊。'],
  ['其卒不赴告，諱之也。', '他的死訊沒有正式報告天下，因為周人想避諱這件事。']
  ,['立昭王子滿，是為穆王。', '昭王的兒子滿繼位，這就是周穆王。']
  ,['穆王即位，春秋已五十矣。', '穆王即位時，已經五十歲了。']
  ,['王道衰微，穆王閔文武之道缺，乃命伯臩申誡太僕國之政，作《臩命》。', '王道逐漸衰微，穆王憂慮文王、武王的治道有所缺失，便命伯臩重新告誡太僕治理國政的原則，撰作《臩命》。']
  ,['復寧。', '天下重新安定。']
  ,['穆王將徵犬戎，祭公謀父諫曰：「不可。', '穆王準備征伐犬戎，祭公謀父勸諫說：「不可以。']
  ,['先王燿德不觀兵。', '先王彰明德行，不炫耀武力。']
  ,['夫兵戢而時動，動則威，觀則玩，玩則無震。', '兵器應當收藏，只有在適當時機才動用；動用才會顯示威嚴，若只是展示，就會變成玩物，成為玩物便失去震懾力。']
  ,['是故周文公之頌曰：『載戢干戈，載櫜弓矢，我求懿德，肆於時夏，允王保之。', '所以周文公的頌歌說：「收起盾牌和兵器，收藏弓箭；我追求美善的德行，把它施行在華夏，這樣才確實能使君王守住天下。」']
  ,['先王之於民也，茂正其德而厚其性，阜其財求而利其器用，明利害之鄉，以文修之，使之務利而闢害，懷德而畏威，故能保世以滋大。', '先王治理百姓，努力端正他們的德行，使本性淳厚；增加財貨，改善器用；說明利害的方向，再用禮義教化他們，使他們追求利益、避開禍害，感念德澤而敬畏威勢，因此能守住國家，使基業日益壯大。']
  ,['』先王之於民也，茂正其德而厚其性，阜其財求而利其器用，明利害之鄉，以文修之，使之務利而闢害，懷德而畏威，故能保世以滋大。', '先王治理百姓，努力端正他們的德行，使本性淳厚；增加財貨，改善器用；說明利害的方向，再用禮義教化他們，使他們追求利益、避開禍害，感念德澤而敬畏威勢，因此能守住國家，使基業日益壯大。']
  ,['昔我先王世后稷以服事虞、夏。', '從前我們的先王世代擔任后稷，侍奉虞舜和夏朝。']
  ,['及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎狄之閒。', '夏朝衰落時，朝廷不再重視農官；我們的先王不窋因此失去官職，只好自行逃到戎狄之間。']
  ,['不敢怠業，時序其德，遵修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信。', '他不敢怠慢祖業，及時整理先人的德業，遵循並修治傳統，整理祖先的教訓與典籍，早晚恭敬勤勉，以敦厚守持，以忠信奉行。']
  ,['奕世載德，不忝前人。', '世世代代承載德行，沒有辱沒前人。']
  ,['至於文王、武王，昭前之光明而加之以慈和，事神保民，無不欣喜。', '到了文王、武王，他們彰顯前人的光明德業，又增添慈愛和諧，敬事神明、保護百姓，人人都感到喜悅。']
  ,['商王帝辛大惡於民，庶民不忍，訢載武王，以致戎於商牧。', '商王帝辛對百姓作惡多端，百姓不能忍受，歡迎武王，於是武王把軍隊帶到商郊牧野。']
  ,['是故先王非務武也，勸恤民隱而除其害也。', '所以先王並不是專意尚武，而是勉力體恤百姓的苦難，為他們除去禍害。']
  ,['夫先王之制，邦內甸服，邦外侯服，侯衛賓服，夷蠻要服，戎翟荒服。', '先王的制度是：王畿內為甸服，王畿外為侯服，諸侯和衛國為賓服，夷狄為要服，戎狄更遠的地方為荒服。']
  ,['甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。', '甸服按時祭祀，侯服舉行祀典，賓服進獻享禮，要服進貢，荒服來朝見天子。']
  ,['日祭，月祀，時享，歲貢，終王。', '甸服每日祭祀，侯服每月祭祀，賓服按季進獻，要服每年進貢，荒服終年來朝王。']
  ,['先王之順祀也，有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。', '先王按照這套秩序接受朝貢祭祀：有人不祭，就修正對方的心意；不祀，就修正告誡之辭；不享，就修正文書；不貢，就修正名分；不來朝王，就修明德政；秩序已成而仍有人不到，才修治刑法。']
  ,['於是有刑不祭，伐不祀，徵不享，讓不貢，告不王。', '因此，不祭就施刑，不祀就出兵討伐，不享就征討，不貢就責讓，不來朝王就發布告誡。']
  ,['於是有刑罰之闢，有攻伐之兵，有徵討之備，有威讓之命，有文告之辭。', '於是才有刑罰的法令、攻伐的軍隊、征討的準備、威嚴責讓的命令，以及正式告誡的文辭。']
  ,['布令陳辭而有不至，則增修於德，無勤民於遠。', '發布命令、陳述道理後仍有人不到，就應更加修養德政，不要讓遠方百姓疲於奔命。']
  ,['是以近無不聽，遠無不服。', '因此近處沒有不聽命的，遠方也沒有不服從的。']
  ,['今自大畢、伯士之終也，犬戎氏以其職來王，天子曰『予必以不享徵之，且觀之兵』，無乃廢先王之訓，而王幾頓乎？', '如今自大畢、伯士去世以來，犬戎本來依照職分前來朝王，天子卻說：「我一定要因為他們不進獻而征討，並且展示軍力。」這恐怕會背棄先王的教訓，使王業幾乎敗亡吧？']
  ,['吾聞犬戎樹敦，率舊德而守終純固，其有以御我矣。', '我聽說犬戎敦厚樸實，遵循舊有德行，始終守持堅固，他們恐怕有能力抵抗我們。']
  ,['」王遂徵之，得四白狼四白鹿以歸。', '穆王仍然出兵征伐，帶著四隻白狼和四隻白鹿回來。']
  ,['自是荒服者不至。', '從此以後，荒服地區的部族不再前來朝見。']
  ,['諸侯有不睦者，甫侯言於王，作《修刑辟》。', '諸侯中有不和睦的，甫侯把情況告訴穆王，撰作《修刑辟》。']
  ,['王曰：「籲，來！', '穆王說：「唉，來吧！']
  ,['有國有土，告汝祥刑。', '有國家、有土地的諸侯，我告訴你們施行刑法的正道。']
  ,['在今爾安百姓，何擇非其人，何敬非其刑，何居非其宜與？', '如今你們要使百姓安定，怎能任用不合適的人？怎能把刑法當作不值得敬畏的事？怎能把職位放在不適當的地方？']
  ,['兩造具備，師聽五辭。', '訴訟雙方都到齊後，由司法官聽取五種供詞。']
  ,['五辭簡信，正於五刑。', '五種供詞經查驗而可信，就依五刑判決。']
  ,['五刑不簡，正於五罰。', '五刑不足以確定罪責，就依五罰判決。']
  ,['五罰不服，正於五過。', '五罰仍不能使人服罪，就依五種過失判定。']
  ,['五過之疵，官獄內獄，閱實其罪，惟鈞其過。', '五種過失有疑點時，官府內外的獄訟都要核查罪狀，實事求是地判定相應的過失。']
  ,['五刑之疑有赦，五罰之疑有赦，其審克之。', '五刑有疑問的可以赦免，五罰有疑問的也可以赦免；你們務必審慎判斷。']
  ,['簡信有眾，惟訊有稽。', '查驗可信的證據要有眾人參與，訊問也要有根據可考。']
  ,['無簡不疑，共嚴天威。', '凡未經查驗、仍有疑問的，不要妄下判決；共同敬畏上天的威嚴。']
  ,['黥闢疑赦，其罰百率，閱實其罪。', '墨刑的案件若有疑問而獲赦免，就改處一百鍰的罰金，並核查實際罪狀。']
  ,['劓闢疑赦，其罰倍灑，閱實其罪。', '劓刑的案件若有疑問而獲赦免，就處兩百鍰的罰金，並核查實際罪狀。']
  ,['臏闢疑赦，其罰倍差，閱實其罪。', '剕刑的案件若有疑問而獲赦免，就依規定處以加重的罰金，並核查實際罪狀。']
  ,['宮闢疑赦，其罰五百率，閱實其罪。', '宮刑的案件若有疑問而獲赦免，就處五百鍰的罰金，並核查實際罪狀。']
  ,['大辟疑赦，其罰千率，閱實其罪。', '死刑的案件若有疑問而獲赦免，就處一千鍰的罰金，並核查實際罪狀。']
  ,['墨罰之屬千，劓罰之屬千，臏罰之屬五百，宮罰之屬三百，大辟之罰其屬二百：五刑之屬三千。', '墨刑所屬的罪名有一千種，劓刑一千種，剕刑五百種，宮刑三百種，死刑所屬的罪名二百種，五刑合計三千種。']
  ,['」命曰甫刑。', '這套刑法命名為《甫刑》。']
  ,['穆王立五十五年，崩，子共王繄扈立。', '穆王在位五十五年去世，兒子繄扈繼位，這就是共王。']
  ,['共王遊於涇上，密康公從，有三女奔之。', '共王在涇水岸邊遊覽，密康公跟隨在旁，有三名女子投奔他。']
  ,['其母曰：「必致之王。', '她們的母親說：「一定要把她們獻給共王。']
  ,['夫獸三為羣，人三為眾，女三為粲。', '野獸三隻就成群，人三個就成眾，女子三人聚在一起就稱為粲。']
  ,['王田不取羣，公行不下眾，王御不參一族。', '君王打獵不捕取成群的野獸，諸侯出行不在眾人面前屈居下位，君王駕車也不讓同一族的三名女子同時陪侍。']
  ,['夫粲，美之物也。', '粲是美好的事物。']
  ,['眾以美物歸女，而何德以堪之？', '眾人把美好之物歸給女子，你有什麼德行承受得起呢？']
  ,['王猶不堪，況爾之小醜乎！', '連君王都未必承受得起，何況你這個小小的諸侯呢！']
  ,['小醜備物，終必亡。', '小諸侯若擁有超出身分的美物，最後一定會滅亡。']
  ,['」康公不獻，一年，共王滅密。', '康公沒有把女子獻給共王；一年後，共王滅掉了密國。']
  ,['共王崩，子懿王艱立。', '共王去世，兒子艱繼位，這就是懿王。']
  ,['懿王之時，王室遂衰，詩人作刺。', '懿王在位時，周王室便開始衰弱，詩人因此創作諷刺詩。']
  ,['懿王崩，共王弟闢方立，是為孝王。', '懿王去世，共王的弟弟闢方繼位，這就是孝王。']
  ,['孝王崩，諸侯復立懿王太子燮，是為夷王。', '孝王去世，諸侯再次擁立懿王的太子燮，這就是夷王。']
  ,['夷王崩，子厲王胡立。', '夷王去世，兒子胡繼位，這就是厲王。']
  ,['厲王即位三十年，好利，近榮夷公。', '厲王即位三十年時，貪好財利，親近榮夷公。']
  ,['大夫芮良夫諫厲王曰：「王室其將卑乎？', '大夫芮良夫勸諫厲王說：「王室恐怕要衰微了吧？']
  ,['夫榮公好專利而不知大難。', '榮公喜歡獨佔財利，卻不知道這會帶來大禍。']
  ,['夫利，百物之所生也，天地之所載也，而有專之，其害多矣。', '財利是萬物產生的資源，也是天地承載的東西，若有人想獨自占有，造成的禍害就多了。']
  ,['天地百物皆將取焉，何可專也？', '天地間的萬物都要從中取用，怎麼可以獨佔呢？']
  ,['所怒甚多，不備大難。', '被激怒的人會非常多，卻沒有防備即將到來的大禍。']
  ,['以是教王，王其能久乎？', '我正因此勸告大王，王室還能長久嗎？']
  ,['夫王人者，將導利而布之上下者也。', '做君王的人，應當引導財利的流通，把它分布給上下各方。']
  ,['使神人百物無不得極，猶日怵惕懼怨之來也。', '要使神明、百姓和萬物都能得到充分的利益，即使如此，每天仍應警惕，害怕怨恨到來。']
  ,['故《頌》曰『思文后稷，克配彼天，立我蒸民，莫匪爾極』。', '所以《頌》說：「想念文德昭著的后稷，他足以配合上天，養育我們眾民，沒有一件事不是你的功勞。」']
  ,['大雅曰『陳錫載周』。', '《大雅》說：「廣泛施予恩賜，使周朝得以承載延續。」']
  ,['是不布利而懼難乎，故能載周以至於今。', '這不就是把利益分布給眾人、同時害怕禍難嗎？所以周朝才能延續到今天。']
  ,['今王學專利，其可乎？', '現在大王卻學著獨佔財利，這怎麼可以呢？']
  ,['匹夫專利，猶謂之盜，王而行之，其歸鮮矣。', '普通人獨佔財利，尚且會被稱為盜賊；君王若這樣做，歸附他的人就少了。']
  ,['榮公若用，周必敗也。', '如果任用榮公，周朝一定會敗亡。」']
  ,['」厲王不聽，卒以榮公為卿士，用事。', '厲王不聽，最後仍任用榮公為卿士，讓他掌管政事。']
  ,['王行暴虐侈傲，國人謗王。', '厲王施政暴虐、奢侈而傲慢，國人紛紛批評他。']
  ,['召公諫曰：「民不堪命矣。', '召公勸諫說：「百姓已經承受不了命令和苛政了。']
  ,['」王怒，得衛巫，使監謗者，以告則殺之。', '厲王大怒，找來衛國的巫師，派他監視批評自己的人；巫師一告發，厲王就殺掉那人。']
  ,['其謗鮮矣，諸侯不朝。', '批評厲王的人變少了，諸侯也不再來朝見。']
  ,['三十四年，王益嚴，國人莫敢言，道路以目。', '厲王三十四年，君王更加嚴酷，國人沒有人敢說話，只能在道路上用眼神互相示意。']
  ,['厲王喜，告召公曰：「吾能弭謗矣，乃不敢言。', '厲王很高興，告訴召公：「我已經能制止批評了，百姓再也不敢說話。']
  ,['」召公曰：「是鄣之也。', '召公說：「這只是把言論堵住了。']
  ,['防民之口，甚於防水。', '堵住百姓的嘴，比堵住洪水更危險。']
  ,['水壅而潰，傷人必多，民亦如之。', '水被堵住後潰決，傷害的人一定很多；百姓的言論也是如此。']
  ,['是故為水者決之使導，為民者宣之使言。', '所以治水的人要挖開通道使水流走，治理百姓的人要疏通言路讓他們說話。']
  ,['故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽史教誨，耆艾修之，而後王斟酌焉，是以事行而不悖。', '所以天子處理政事時，要讓公卿直到列士獻詩，樂官獻樂曲，史官獻史書，樂師進箴言，失明的樂官朗誦，百官進諫，平民傳達意見；近臣盡力規勸，親族補充察核，樂官和史官教誨，年長者修正，然後君王斟酌採納，事情才能推行而不違背道理。']
  ,['民之有口也，猶土之有山川也，財用於是乎出：猶其有原隰衍沃也，衣食於是乎生。', '百姓有嘴，就像土地有山川一樣，財貨由此產生；又像土地有平原、低濕地和肥沃之處，衣食由此生長。']
  ,['口之宣言也，善敗於是乎興。', '百姓把話說出來，善政和敗政也因此顯現。']
  ,['行善而備敗，所以產財用衣食者也。', '施行善政並防止敗政，正是使財貨、日用和衣食得以產生的原因。']
  ,['夫民慮之於心而宣之於口，成而行之。', '百姓先在心中思考，再從口中說出，事情成熟後便付諸實行。']
  ,['若壅其口，其與能幾何？', '如果堵住他們的嘴，國家還能維持多久呢？']
  ,['」王不聽。', '厲王不肯聽從。']
  ,['於是國莫敢出言，三年，乃相與畔，襲厲王。', '從此國人沒有敢說話的；三年後，大家一起反叛，攻擊厲王。']
  ,['厲王出奔於彘。', '厲王逃到彘地。']
  ,['厲王太子靜匿召公之家，國人聞之，乃圍之。', '厲王的太子靜藏在召公家中，國人得知後，便包圍召公的宅第。']
  ,['召公曰：「昔吾驟諫王，王不從，以及此難也。', '召公說：「從前我多次勸諫厲王，他不聽，才造成今天的災難。']
  ,['今殺王太子，王其以我為讎而懟怒乎？', '現在如果殺死王太子，厲王恐怕會把我當作仇人而怨怒吧？']
  ,['夫事君者，險而不讎懟，怨而不怒，況事王乎！', '侍奉君主的人，身處危險也不應結怨，受到怨恨也不應發怒，何況是侍奉天子呢！']
  ,['」乃以其子代王太子，太子竟得脫。', '於是召公用自己的兒子代替太子，太子終於得以逃脫。']
  ,['召公、周公二相行政，號曰「共和」。', '召公、周公兩位宰相共同執行政務，這段時期稱為「共和」。']
  ,['共和十四年，厲王死於彘。', '共和十四年，厲王死在彘地。']
  ,['太子靜長於召公家，二相乃共立之為王，是為宣王。', '太子靜在召公家中長大，兩位宰相於是共同擁立他為王，這就是宣王。']
  ,['宣王即位，二相輔之，修政，法文、武、成、康之遺風，諸侯復宗周。', '宣王即位後，兩位宰相輔佐他整頓政事，效法文王、武王、成王、康王留下的傳統，諸侯重新尊奉周王室。']
  ,['十二年，魯武公來朝。', '宣王十二年，魯武公前來朝見。']
  ,['宣王不修籍於千畝，虢文公諫曰不可，王弗聽。', '宣王沒有親自到千畝舉行籍田禮，虢文公勸諫說不可以，宣王不聽。']
  ,['三十九年，戰於千畝，王師敗績於姜氏之戎。', '宣王三十九年，周軍在千畝與姜姓戎人交戰，王師大敗。']
  ,['宣王既亡南國之師，乃料民於太原。', '宣王失去南方諸侯的軍隊後，便在太原清點百姓人數。']
  ,['仲山甫諫曰：「民不可料也。', '仲山甫勸諫說：「百姓不可以這樣清點。']
  ,['」宣王不聽，卒料民。', '宣王不聽，最後仍清點了百姓。']
  ,['四十六年，宣王崩，子幽王宮湦立。', '宣王四十六年去世，兒子宮湦繼位，這就是幽王。']
  ,['幽王二年，西周三川皆震。', '幽王二年，西周境內的涇水、渭水、洛水三川都發生地震。']
  ,['伯陽甫曰：「周將亡矣。', '伯陽甫說：「周朝就要滅亡了。']
  ,['夫天地之氣，不失其序；', '天地之氣運行不能失去秩序；']
  ,['若過其序，民亂之也。', '如果超越正常次序，百姓就會因此陷入混亂。']
  ,['陽伏而不能出，陰迫而不能蒸，於是有地震。', '陽氣潛伏而不能升出，陰氣受到壓迫而不能上蒸，因此發生地震。']
  ,['今三川實震，是陽失其所而填陰也。', '如今三條河川確實都在震動，這表示陽氣失去位置，被陰氣壓住了。']
  ,['陽失而在陰，原必塞；', '陽氣失位而陷在陰氣之中，水源一定會堵塞；']
  ,['原塞，國必亡。', '水源堵塞，國家一定會滅亡。']
  ,['夫水土演而民用也。', '水流和土地通暢，百姓才能取用它們。']
  ,['土無所演，民乏財用，不亡何待！', '土地沒有地方疏通，百姓缺乏財貨和資源，不亡國還要等什麼呢！']
  ,['昔伊、洛竭而夏亡，河竭而商亡。', '從前伊水、洛水乾涸，夏朝便滅亡；黃河乾涸，商朝便滅亡。']
  ,['今周德若二代之季矣，其川原又塞，塞必竭。', '如今周朝的德政已像夏、商末年一樣衰敗，河川源頭又堵塞；堵塞之後必然乾涸。']
  ,['夫國必依山川，山崩川竭，亡國之徵也。', '國家必須依靠山川生存；山崩、河川乾涸，就是亡國的徵兆。']
  ,['川竭必山崩。', '河川乾涸後，山一定會崩塌。']
  ,['若國亡不過十年，數之紀也。', '如果周國滅亡，應該不會超過十年，這是天數所定的期限。']
  ,['天之所棄，不過其紀。', '上天所要捨棄的國家，不會超過這個期限。']
  ,['」是歲也，三川竭，岐山崩。', '這一年，三條河川乾涸，岐山崩塌。']
  ,['三年，幽王嬖愛褒姒。', '幽王三年，幽王寵愛褒姒。']
  ,['褒姒生子伯服，幽王欲廢太子。', '褒姒生下兒子伯服，幽王想廢掉太子。']
  ,['太子母申侯女，而為後。', '太子的母親是申侯的女兒，原本立為王后。']
  ,['後幽王得褒姒，愛之，欲廢申後，並去太子宜臼，以褒姒為後，以伯服為太子。', '後來幽王得到褒姒並寵愛她，想廢掉申后，也廢除太子宜臼，改立褒姒為后、伯服為太子。']
  ,['周太史伯陽讀史記曰：「周亡矣。', '周太史伯陽讀史書後說：「周朝要滅亡了。']
  ,['昔自夏后氏之衰也，有二神龍止於夏帝庭而言曰：「餘，褒之二君。', '從前夏后氏衰落時，有兩條神龍停在夏帝庭院，說：「我們是褒地的兩位君主。']
  ,['」夏帝卜殺之與去之與止之，莫吉。', '夏帝占卜要不要殺掉它們、驅逐它們或留下它們，結果都沒有吉兆。']
  ,['卜請其漦而藏之，乃吉。', '再占卜請取龍的唾液收藏起來，才得到吉兆。']
  ,['於是布幣而策告之，龍亡而漦在，櫝而去之。', '於是陳列玉帛並寫策書禱告，神龍消失而唾液留下，夏人把它放進匣子收藏。']
  ,['夏亡，傳此器殷。', '夏朝滅亡後，這件器物傳到了殷。']
  ,['殷亡，又傳此器周。', '殷朝滅亡後，這件器物又傳到了周。']
  ,['比三代，莫敢發之，至厲王之末，發而觀之。', '三代之間沒有人敢打開它，直到厲王末年才有人打開觀看。']
  ,['漦流於庭，不可除。', '龍唾液流到庭院中，怎麼也清除不了。']
  ,['厲王使婦人裸而譟之。', '厲王派婦女裸體在旁喧鬧驅趕。']
  ,['漦化為玄黿，以入王後宮。', '唾液化成黑色的大龜，進入王后的宮中。']
  ,['後宮之童妾既齔而遭之，既笄而孕，無夫而生子，懼而棄之。', '王后宮中的一名童妾年幼換牙時遇到這件事，成年行笄禮後便懷孕，沒有丈夫卻生下孩子，因害怕而把孩子丟棄。']
  ,['宣王之時童女謠曰：「厭弧箕服，實亡周國。', '宣王時，有童女唱歌說：「背著弓、穿著箕形衣服的人，真的會使周國滅亡。']
  ,['於是宣王聞之，有夫婦賣是器者，宣王使執而戮之。', '宣王聽見後，得知有一對夫妻正在販賣這種器物，便命人逮捕並殺死他們。']
  ,['」於是宣王聞之，有夫婦賣是器者，宣王使執而戮之。', '宣王聽見後，得知有一對夫妻正在販賣這種器物，便命人逮捕並殺死他們。']
  ,['逃於道，而見鄉者後宮童妾所棄妖子出於路者，聞其夜啼，哀而收之，夫婦遂亡，奔於褒。', '那對夫妻在逃亡途中，看見先前後宮童妾丟棄、正在路上的妖異嬰兒，聽到他夜裡哭泣，憐憫地收養了他們，夫妻便逃往褒地。']
  ,['褒人有罪，請入童妾所棄女子者於王以贖罪。', '褒地有人犯罪，便請把那名童妾丟棄的女孩獻給宣王，以此贖罪。']
  ,['棄女子出於褒，是為褒姒。', '那名被丟棄的女孩在褒地長大，這就是褒姒。']
  ,['當幽王三年，王之後宮見而愛之，生子伯服，竟廢申後及太子，以褒姒為後，伯服為太子。', '到了幽王三年，幽王在後宮見到褒姒並寵愛她；她生下伯服，幽王最後廢掉申后和太子，立褒姒為后、伯服為太子。']
  ,['太史伯陽曰：「禍成矣，無可奈何！', '太史伯陽說：「禍患已經造成了，沒有辦法挽回！']
  ,['褒姒不好笑，幽王欲其笑萬方，故不笑。', '褒姒不喜歡笑，幽王想盡各種方法逗她笑，她仍然不笑。']
  ,['幽王為烽燧大鼓，有寇至則舉烽火。', '幽王設置烽火台並準備大鼓，敵人來到時就點燃烽火。']
  ,['諸侯悉至，至而無寇，褒姒乃大笑。', '諸侯全都趕來，到了卻沒有敵人，褒姒因此大笑。']
  ,['幽王說之，為數舉烽火。', '幽王很高興，便多次無故點燃烽火。']
  ,['其後不信，諸侯益亦不至。', '後來諸侯不再相信烽火警報，於是更加不肯前來。']
  ,['幽王以虢石父為卿，用事，國人皆怨。', '幽王任用虢石父為卿，讓他掌管政事，國人都因此怨恨。']
  ,['石父為人佞巧善諛好利，王用之。', '石父為人諂媚機巧，善於奉承又貪圖財利，幽王卻任用他。']
  ,['又廢申後，去太子也。', '幽王又廢掉申后，並罷黜太子宜臼。']
  ,['申侯怒，與繒、西夷犬戎攻幽王。', '申侯大怒，聯合繒國和西方的犬戎進攻幽王。']
  ,['幽王舉烽火徵兵，兵莫至。', '幽王點燃烽火召集諸侯軍隊，卻沒有軍隊前來。']
  ,['遂殺幽王驪山下，虜褒姒，盡取周賂而去。', '聯軍於是把幽王殺死在驪山下，俘虜褒姒，劫走周朝的財物後離去。']
  ,['於是諸侯乃即申侯而共立故幽王太子宜臼，是為平王，以奉周祀。', '諸侯於是依靠申侯，共同擁立原幽王太子宜臼，這就是平王，讓他承繼周朝祭祀。']
  ,['平王立，東遷於雒邑，闢戎寇。', '平王即位後，把都城向東遷到雒邑，以躲避戎人的侵擾。']
  ,['平王之時，周室衰微，諸侯彊並弱，齊、楚、秦、晉始大，政由方伯。', '平王時期，周王室衰弱，強大的諸侯兼併弱小諸侯；齊、楚、秦、晉開始壯大，政令由各地霸主掌握。']
  ,['四十九年，魯隱公即位。', '平王四十九年，魯隱公即位。']
  ,['五十一年，平王崩，太子洩父早死，立其子林，是為桓王。', '平王五十一年去世，太子洩父早已去世，於是立洩父的兒子林，這就是桓王。']
  ,['桓王，平王孫也。', '桓王是平王的孫子。']
  ,['桓王三年，鄭莊公朝，桓王不禮。', '桓王三年，鄭莊公前來朝見，桓王沒有按照禮節接待他。']
  ,['五年，鄭怨，與魯易許田。', '桓王五年，鄭國因此怨恨周王室，與魯國交換許田。']
  ,['許田，天子之用事太山田也。', '許田是天子到泰山舉行祭祀時使用的田地。']
  ,['八年，魯殺隱公，立桓公。', '桓王八年，魯國殺死隱公，改立桓公。']
  ,['十三年，伐鄭，鄭射傷桓王，桓王去歸。', '桓王十三年，周王室出兵討伐鄭國；鄭軍射傷桓王，桓王只好離開返回。']
  ,['二十三年，桓王崩，子莊王佗立。', '桓王二十三年去世，兒子佗繼位，這就是莊王。']
  ,['莊王四年，周公黑肩欲殺莊王而立王子克。', '莊王四年，周公黑肩想殺掉莊王，改立王子克。']
  ,['辛伯告王，王殺周公。', '辛伯把這件事告訴莊王，莊王便殺死周公黑肩。']
  ,['王子克奔燕。', '王子克逃往燕國。']
  ,['十五年，莊王崩，子釐王胡齊立。', '莊王十五年去世，兒子胡齊繼位，這就是釐王。']
  ,['釐王三年，齊桓公始霸。', '釐王三年，齊桓公開始成為諸侯霸主。']
  ,['五年，釐王崩，子惠王閬立。', '釐王五年去世，兒子閬繼位，這就是惠王。']
  ,['惠王二年。', '惠王在位第二年。']
  ,['初，莊王嬖姬姚，生子穨，穨有寵。', '起初，莊王寵愛姬妾姚氏，姚氏生下王子穨，穨也受到寵愛。']
  ,['及惠王即位，奪其大臣以為囿，故大夫邊伯等五人作亂，謀召燕、衛師，伐惠王。', '惠王即位後，把大臣的土地奪來建造苑囿，因此大夫邊伯等五人作亂，計畫召來燕、衛兩國的軍隊討伐惠王。']
  ,['惠王犇溫，已居鄭之櫟。', '惠王逃到溫地，後來住在鄭國的櫟地。']
  ,['立釐王弟穨為王。', '叛亂者擁立釐王的弟弟穨為王。']
  ,['樂及徧舞，鄭、虢君怒。', '穨奏樂並讓舞者全部起舞，鄭君和虢君因此大怒。']
  ,['四年，鄭與虢君伐殺王穨，復入惠王。', '惠王四年，鄭君和虢君出兵殺死王穨，重新迎回惠王。']
  ,['惠王十年，賜齊桓公為伯。', '惠王十年，周王賜予齊桓公霸主的名位。']
  ,['二十五年，惠王崩，子襄王鄭立。', '惠王二十五年去世，兒子鄭繼位，這就是襄王。']
  ,['襄王母蚤死，後母曰惠後。', '襄王的生母早逝，後來的嫡母稱為惠后。']
  ,['惠後生叔帶，有寵於惠王，襄王畏之。', '惠后生下叔帶，叔帶受到惠王寵愛，襄王因此畏懼他。']
  ,['三年，叔帶與戎、翟謀伐襄王，襄王欲誅叔帶，叔帶奔齊。', '襄王三年，叔帶和戎、翟聯絡，計畫攻打襄王；襄王想誅殺叔帶，叔帶便逃到齊國。']
  ,['齊桓公使管仲平戎於周，使隰朋平戎於晉。', '齊桓公派管仲到周地平息戎人的衝突，又派隰朋到晉地處理戎患。']
  ,['王以上卿禮管仲。', '周王用上卿的禮節接待管仲。']
  ,['管仲辭曰：「臣賤有司也，有天子之二守國、高在。', '管仲推辭說：「我是地位卑下的有司，何況天子已有兩位守臣國、高在此。']
  ,['若節春秋來承王命，何以禮焉。', '如果只是依照春秋時節前來承受王命，怎麼能用上卿的禮節接待我呢？']
  ,['陪臣敢辭。', '我只是諸侯的臣下，不敢接受這種禮遇。」']
  ,['」王曰：「舅氏，餘嘉乃勳，毋逆朕命。', '周王說：「舅父，我很嘉許你的功勞，不要違背我的命令。」']
  ,['」管仲卒受下卿之禮而還。', '管仲最後接受下卿的禮節，然後返回齊國。']
  ,['九年，齊桓公卒。', '襄王九年，齊桓公去世。']
  ,['十二年，叔帶復歸於周。', '襄王十二年，叔帶再次回到周地。']
  ,['十三年，鄭伐滑，王使遊孫、伯服請滑，鄭人囚之。', '襄王十三年，鄭國攻打滑國；周王派遊孫和伯服向鄭國請求保全滑國，鄭人把他們囚禁起來。']
  ,['鄭文公怨惠王之入不與厲公爵，又怨襄王之與衛滑，故囚伯服。', '鄭文公怨恨惠王入周時沒有給鄭厲公封爵，也怨恨襄王支持衛國和滑國，所以囚禁伯服。']
  ,['王怒，將以翟伐鄭。', '周王大怒，準備聯合翟人討伐鄭國。']
  ,['富辰諫曰：「凡我周之東徙，晉、鄭焉依。', '富辰勸諫說：「當初我們周室向東遷徙，依靠的是晉國和鄭國。']
  ,['子穨之亂，又鄭之由定，今以小怨棄之！', '王子穨作亂時，也是靠鄭國才平定；如今卻因小小的怨恨就拋棄鄭國！']
  ,['」王不聽。', '周王不聽。']
  ,['十五年，王降翟師以伐鄭。', '襄王十五年，周王率領翟軍討伐鄭國。']
  ,['王德翟人，將以其女為後。', '周王感激翟人，打算立翟人的女兒為王后。']
  ,['富辰諫曰：「平、桓、莊、惠皆受鄭勞，王棄親親翟，不可從。', '富辰勸諫說：「平王、桓王、莊王、惠王都受過鄭國的功勞；大王若拋棄親近的鄭國而親近翟人，不可以這樣做。']
  ,['」王不聽。', '周王不聽。']
  ,['十六年，王絀翟後，翟人來誅，殺譚伯。', '襄王十六年，周王廢掉翟后，翟人前來討伐，殺死譚伯。']
  ,['富辰曰：「吾數諫不從。', '富辰說：「我多次勸諫都沒有被採納。']
  ,['如是不出，王以我為懟乎？', '如果這次不出兵，大王會認為我在怨恨你嗎？']
  ,['」乃以其屬死之。', '於是富辰帶著自己的部屬戰死。']
  ,['初，惠後欲立王子帶，故以黨開翟人，翟人遂入周。', '起初，惠后想擁立王子帶，所以利用自己的黨羽聯絡翟人，翟人於是攻入周地。']
  ,['襄王出奔鄭，鄭居王於汜。', '襄王逃到鄭國，鄭國把他安置在汜地。']
  ,['子帶立為王，取襄王所絀翟後與居溫。', '王子帶被擁立為王，並帶著襄王廢掉的翟后住在溫地。']
  ,['十七年，襄王告急於晉，晉文公納王而誅叔帶。', '襄王十七年，襄王向晉國告急；晉文公接回襄王，並誅殺叔帶。']
  ,['襄王乃賜晉文公珪鬯弓矢，為伯，以河內地與晉。', '襄王於是賞賜晉文公玉圭、鬯酒、弓箭，封他為霸主，並把河內土地給了晉國。']
  ,['二十年，晉文公召襄王，襄王會之河陽、踐土，諸侯畢朝，書諱曰「天王狩於河陽」。', '襄王二十年，晉文公召集襄王，襄王在河陽、踐土與諸侯會面，諸侯都來朝見；史書避諱晉文公召王，寫成「天王在河陽巡狩」。']
  ,['二十四年，晉文公卒。', '襄王二十四年，晉文公去世。']
  ,['三十一年，秦穆公卒。', '襄王三十一年，秦穆公去世。']
  ,['三十二年，襄王崩，子頃王壬臣立。', '襄王三十二年去世，兒子壬臣繼位，這就是頃王。']
  ,['頃王六年，崩，子匡王班立。', '頃王六年去世，兒子班繼位，這就是匡王。']
  ,['匡王六年，崩，弟瑜立，是為定王。', '匡王六年去世，弟弟瑜繼位，這就是定王。']
  ,['定王元年，楚莊王伐陸渾之戎，次洛，使人問九鼎。', '定王元年，楚莊王討伐陸渾的戎人，軍隊駐紮在洛水附近，派人詢問九鼎的大小輕重。']
  ,['王使王孫滿應設以辭，楚兵乃去。', '周王派王孫滿用言辭應對，楚軍於是撤退。']
  ,['十年，楚莊王圍鄭，鄭伯降，已而復之。', '定王十年，楚莊王包圍鄭國，鄭伯投降；不久楚莊王又恢復他的君位。']
  ,['十六年，楚莊王卒。', '定王十六年，楚莊王去世。']
  ,['二十一年，定王崩，子簡王夷立。', '定王二十一年去世，兒子夷繼位，這就是簡王。']
  ,['簡王十三年，晉殺其君厲公，迎子周於周，立為悼公。', '簡王十三年，晉國殺死國君厲公，從周地迎接子周，立他為晉悼公。']
  ,['十四年，簡王崩，子靈王泄心立。', '簡王十四年去世，兒子泄心繼位，這就是靈王。']
  ,['靈王二十四年，齊崔杼弒其君莊公。', '靈王二十四年，齊國的崔杼殺死國君莊公。']
  ,['二十七年，靈王崩，子景王貴立。', '靈王二十七年去世，兒子貴繼位，這就是景王。']
  ,['景王十八年，後太子聖而蚤卒。', '景王十八年，王后所生的太子聖早逝。']
  ,['二十年，景王愛子朝，欲立之，會崩，子丐之黨與爭立，國人立長子猛為王，子朝攻殺猛。', '景王二十年，景王寵愛王子朝，想立他為太子，卻在此時去世；王子丐的黨羽與王子朝爭奪王位，國人擁立長子猛為王，王子朝出兵殺死猛。']
  ,['猛為悼王。', '猛死後諡為悼王。']
  ,['晉人攻子朝而立丐，是為敬王。', '晉軍攻擊王子朝，擁立王子丐，這就是敬王。']
  ,['敬王元年，晉人入敬王，子朝自立，敬王不得入，居澤。', '敬王元年，晉人護送敬王進入周地，但王子朝自行稱王，敬王無法進入王都，只能住在澤地。']
  ,['四年，晉率諸侯入敬王於周，子朝為臣，諸侯城周。', '敬王四年，晉國率領諸侯護送敬王進入周都，王子朝成為臣下，諸侯替周王修築城牆。']
  ,['十六年，子朝之徒復作亂，敬王奔於晉。', '敬王十六年，王子朝的黨羽再次作亂，敬王逃往晉國。']
  ,['十七年，晉定公遂入敬王於周。', '敬王十七年，晉定公於是再次護送敬王回到周都。']
  ,['三十九年，齊田常殺其君簡公。', '敬王三十九年，齊國的田常殺死國君簡公。']
  ,['四十一年，楚滅陳。', '敬王四十一年，楚國滅掉陳國。']
  ,['孔子卒。', '孔子去世。']
  ,['四十二年，敬王崩，子元王仁立。', '敬王四十二年去世，兒子仁繼位，這就是元王。']
  ,['元王八年，崩，子定王介立。', '元王八年去世，兒子介繼位，這就是定王。']
  ,['定王十六年，三晉滅智伯，分有其地。', '定王十六年，韓、魏、趙三家滅掉智伯，瓜分了他的土地。']
  ,['二十八年，定王崩，長子去疾立，是為哀王。', '定王二十八年去世，長子去疾繼位，這就是哀王。']
  ,['哀王立三月，弟叔襲殺哀王而自立，是為思王。', '哀王即位三個月，弟弟叔突然襲擊並殺死哀王，自立為王，這就是思王。']
  ,['思王立五月，少弟嵬攻殺思王而自立，是為考王。', '思王即位五個月，幼弟嵬出兵殺死思王，自立為王，這就是考王。']
  ,['此三王皆定王之子。', '這三位君王都是定王的兒子。']
  ,['考王十五年，崩，子威烈王午立。', '考王十五年去世，兒子午繼位，這就是威烈王。']
  ,['考王封其弟於河南，是為桓公，以續周公之官職。', '考王把弟弟封在河南，稱為桓公，讓他承續周公的官職。']
  ,['桓公卒，子威公代立。', '桓公去世，兒子威公繼位。']
  ,['威公卒，子惠公代立，乃封其少子於鞏以奉王，號東周惠公。', '威公去世，兒子惠公繼位；惠公又把小兒子封在鞏地侍奉周王，稱為東周惠公。']
  ,['威烈王二十三年，九鼎震。', '威烈王二十三年，九鼎發生震動。']
  ,['命韓、魏、趙為諸侯。', '周王正式任命韓、魏、趙三家為諸侯。']
  ,['二十四年，崩，子安王驕立。', '威烈王二十四年去世，兒子驕繼位，這就是安王。']
  ,['是歲盜殺楚聲王。', '這一年，盜賊殺死楚聲王。']
  ,['安王立二十六年，崩，子烈王喜立。', '安王在位二十六年去世，兒子喜繼位，這就是烈王。']
  ,['烈王二年，周太史儋見秦獻公曰：「始周與秦國合而別，別五百載復合，合十七歲而霸王者出焉。', '烈王二年，周太史儋拜見秦獻公，說：「起初周與秦同出一源，後來分開；分開五百年後會再次合在一起，合在一起十七年後，將有人成為霸主。']
  ,['十年，烈王崩，弟扁立，是為顯王。', '烈王十年去世，弟弟扁繼位，這就是顯王。']
  ,['顯王五年，賀秦獻公，獻公稱伯。', '顯王五年，周王祝賀秦獻公，秦獻公被尊為伯。']
  ,['九年，致文武胙於秦孝公。', '顯王九年，周王把祭祀文王、武王的胙肉送給秦孝公。']
  ,['二十五年，秦會諸侯於周。', '顯王二十五年，秦國在周地會合諸侯。']
  ,['二十六年，周致伯於秦孝公。', '顯王二十六年，周王授予秦孝公伯的名位。']
  ,['三十三年，賀秦惠王。', '顯王三十三年，周王祝賀秦惠王。']
  ,['三十五年，致文武胙於秦惠王。', '顯王三十五年，周王把祭祀文王、武王的胙肉送給秦惠王。']
  ,['四十四年，秦惠王稱王。', '顯王四十四年，秦惠王自稱為王。']
  ,['其後諸侯皆為王。', '從此以後，各諸侯也都自稱為王。']
  ,['四十八年，顯王崩，子慎靚王定立。', '顯王四十八年去世，兒子定繼位，這就是慎靚王。']
  ,['慎靚王立六年，崩，子赧王延立。', '慎靚王在位六年去世，兒子延繼位，這就是赧王。']
  ,['王赧時東西周分治。', '赧王時期，周王室分裂成東周和西周，分別治理。']
  ,['王赧徙都西周。', '赧王把都城遷到西周。']
  ,['西周武公之共太子死，有五庶子，毋適立。', '西周武公的太子去世，留下五名庶子，沒有嫡子可以繼位。']
  ,['司馬翦謂楚王曰：「不如以地資公子咎，為請太子。', '司馬翦對楚王說：「不如把土地送給公子咎，替他請求立為太子。']
  ,['」左成曰：「不可。', '左成說：「不可以。']
  ,['周不聽，是公之知困而交疏於周也。', '周王若不聽從，表示您在周王面前的智謀已經窮盡，和周王的關係也會疏遠。']
  ,['不如請周君孰欲立，以微告翦，翦請令楚（賀）［資］之以地。', '不如先請周王說明想立誰，再暗中告訴司馬翦；司馬翦會請楚王用土地資助這位太子。']
  ,['」果立公子咎為太子。', '結果周人果然立公子咎為太子。']
  ,['八年，秦攻宜陽，楚救之。', '赧王八年，秦國攻打宜陽，楚國出兵救援。']
  ,['而楚以周為秦故，將伐之。', '楚國卻認為周王室偏袒秦國，準備攻打周。']
  ,['蘇代為周說楚王曰：「何以周為秦之禍也？', '蘇代替周王室遊說楚王：「為什麼要把秦國造成的禍患算在周王室頭上呢？']
  ,['言周之為秦甚於楚者，欲令周入秦也，故謂『周秦』也。', '有人說周比楚更親近秦，是想讓周投靠秦國，所以才把周、秦並稱。']
  ,['周知其不可解，必入於秦，此為秦取周之精者也。', '周王室知道自己無法解除這個誤會，就一定會投靠秦國；這正是替秦國取得周地的最好辦法。']
  ,['為王計者，周於秦因善之，不於秦亦言善之，以疏之於秦。', '替大王計策，不如對周表示友善，卻不要在秦面前替周說好話，讓周與秦逐漸疏遠。']
  ,['周絕於秦，必入於郢矣。', '周若與秦斷絕關係，就一定會投靠楚都郢。']
  ,['秦借道兩周之閒，將以伐韓，周恐借之畏於韓，不借畏於秦。', '秦國想借道東周和西周之間去攻打韓國，周王室害怕借道會得罪韓國，不借道又害怕秦國。']
  ,['史厭謂周君曰：「何不令人謂韓公叔曰『秦之敢絕周而伐韓者，信東周也。', '史厭對周君說：「為什麼不派人告訴韓國的公叔說：『秦國敢於越過周地攻打韓國，是因為相信東周會答應借道。']
  ,['公何不與周地，發質使之楚』？', '您為什麼不把土地給周，並派人到楚國作人質呢？』']
  ,['秦必疑楚不信周，是韓不伐也。', '秦國一定會懷疑楚國不信任周，這樣就不會攻打韓國。']
  ,['又謂秦曰『韓彊與周地，將以疑周於秦也，周不敢不受』。', '再告訴秦國說：『韓國強迫周接受土地，是想讓秦懷疑周，周不敢不接受。』']
  ,['秦必無辭而令周不受，是受地於韓而聽於秦。', '秦國一定會找不到理由，卻會命令周不要接受；這樣周既得到韓地，又能聽從秦國。']
  ,['秦召西周君，西周君惡往，故令人謂韓王曰：「秦召西周君，將以使攻王之南陽也，王何不出兵於南陽？', '秦國召西周君入秦，西周君不想前往，便派人告訴韓王：「秦召我國君去，將要利用他攻打大王的南陽；大王為什麼不先在南陽出兵？']
  ,['周君將以為辭於秦。', '這樣周君就可以拿出兵作為不入秦的理由。']
  ,['周君不入秦，秦必不敢踰河而攻南陽矣。', '周君若不入秦，秦國一定不敢越過黃河攻打南陽。」']
  ,['東周與西周戰，韓救西周。', '東周和西周交戰，韓國出兵救援西周。']
  ,['或為東周說韓王曰：「西周故天子之國，多名器重寶。', '有人替東周遊說韓王：「西周原本是天子的國家，擁有許多象徵名分的器物和珍貴寶物。']
  ,['王案兵毋出，可以德東周，而西周之寶必可以盡矣。', '大王只要按兵不動，不出兵，就能向東周施恩，而西周的寶物也一定會被耗盡。」']
  ,['王赧謂成君。', '赧王把這件事告訴成君。']
  ,['楚圍雍氏，韓徵甲與粟於東周，東周君恐，召蘇代而告之。', '楚國包圍雍氏，韓國向東周徵收兵器和糧食；東周君害怕，召來蘇代告訴他這件事。']
  ,['代曰：「君何患於是。', '蘇代說：「君王不必為此憂慮。']
  ,['臣能使韓毋徵甲與粟於周，又能為君得高都。', '我能使韓國不再向周徵收兵器和糧食，還能替君王取得高都。']
  ,['」周君曰：「子茍能，請以國聽子。', '周君說：「如果你真能做到，我願把國政交給你。']
  ,['」代見韓相國曰：「楚圍雍氏，期三月也，今五月不能拔，是楚病也。', '蘇代拜見韓相國說：「楚國包圍雍氏，原定三個月攻下，如今五個月還不能攻破，這表示楚國已經疲弱。']
  ,['今相國乃徵甲與粟於周，是告楚病也。', '現在相國卻向周徵收兵器和糧食，等於把楚國疲弱的消息告訴楚國。']
  ,['韓相國曰：「善。使者已行矣。', '韓相國說：「有道理，使者已經出發了。」']
  ,['代曰：「何不與周高都？', '蘇代說：「為什麼不把高都給周呢？』']
  ,['韓相國大怒曰：「吾毋徵甲與粟於周亦已多矣，何故與周高都也？', '韓相國大怒說：「我不向周徵收兵器和糧食，已經是很大的讓步了，為什麼還要把高都給周呢？』']
  ,['代曰：「與周高都，是周折而入於韓也，秦聞之必大怒忿周，即不通周使，是以獘高都得完周也。', '蘇代說：「把高都給周，就等於使周轉而歸附韓國；秦國聽到後一定會大怒，從此不再接納周的使者。這樣雖然失去高都，卻能保全周國。']
  ,['曷為不與？', '為什麼不給呢？」']
  ,['相國曰：「善。', '韓相國說：「有道理。']
  ,['」果與周高都。', '韓國果然把高都給了周。']
  ,['今又將兵出塞攻梁，梁破則周危矣。', '如今白起又將率軍出關攻打魏國，魏國一旦被攻破，周國也危險了。']
  ,['君何不令人說白起乎？', '君王為什麼不派人去勸說白起呢？']
  ,['曰『楚有養由基者，善射者也。', '可以對他說：『楚國有個叫養由基的人，箭術非常高明。']
  ,['去柳葉百步而射之，百發而百中之。', '他在百步之外射柳葉，射一百箭就命中一百箭。']
  ,['左右觀者數千人，皆曰善射。', '旁邊觀看的幾千人都說他善於射箭。']
  ,['有一夫立其旁，曰「善，可教射矣」。', '有一個人站在他旁邊說：「射得好，但還可以教他射箭。」']
  ,['養由基怒，釋弓搤劍，曰「客安能教我射乎」？', '養由基大怒，放下弓、按住劍，說：「你怎麼能教我射箭呢？」']
  ,['客曰「非吾能教子支左詘右也。', '那人說：「我不是要教你左手支弓、右手彎弦的技術。']
  ,['夫去柳葉百步而射之，百發而百中之，不以善息，少焉氣衰力倦，弓撥矢鉤，一發不中者，百發盡息」。', '你在百步外射柳葉，百發百中，如果不趁技藝正好時收手，過一會兒氣力衰竭，弓弦鬆弛、箭也偏斜，只要一箭不中，先前百發百中的名聲就全毀了。』']
  ,['今破韓、魏，撲師武，北取趙藺、離石者，公之功多矣。', '如今您攻破韓、魏，擊敗武安君的軍隊，又向北攻取趙國的藺和離石，功勞已經很大了。']
  ,['今又將兵出塞，過兩周，倍韓，攻梁，一舉不得，前功盡棄。', '如今又要率軍出關，經過東周、西周，背離韓國而攻打魏國；如果一次失敗，先前的功勞就會全部喪失。']
  ,['公不如稱病而無出』。', '您不如假稱有病，不要出兵。』']
  ,['四十二年，秦破華陽約。', '赧王四十二年，秦國破壞了華陽之約。']
  ,['馬犯謂周君曰：「請令梁城周。', '馬犯對周君說：「請讓魏國替周國修築城牆。']
  ,['」乃謂梁王曰：「周王病若死，則犯必死矣。', '於是他對魏王說：「周王病重，如果去世，我馬犯也一定會死。']
  ,['犯請以九鼎自入於王，王受九鼎而圖犯。', '我請求帶著九鼎親自進入大王之國，大王接受九鼎後就可以處置我。』']
  ,['」梁王曰：「善。', '魏王說：「好。']
  ,['」遂與之卒，言戍周。', '於是給他士兵，名義上說是去守衛周國。']
  ,['因謂秦王曰：「梁非戍周也，將伐周也。', '馬犯又對秦王說：「魏國不是去守衛周國，而是要攻打周國。']
  ,['王試出兵境以觀之。', '大王不妨派兵出境觀察局勢。」']
  ,['」秦果出兵。', '秦國果然出兵。']
  ,['又謂梁王曰：「周王病甚矣，犯請後可而復之。', '馬犯又對魏王說：「周王的病很重，我請求稍後再把士兵撤回。']
  ,['今王使卒之周，諸侯皆生心，後舉事且不信。', '現在大王派軍隊進入周地，諸侯都會產生疑心，以後再採取行動就沒有人相信了。']
  ,['不若令卒為周城，以匿事端。', '不如讓士兵替周國修築城牆，用這個名義掩蓋真正的意圖。']
  ,['」梁王曰：「善。', '魏王說：「好。']
  ,['」遂使城周。', '於是派軍隊替周國修城。']
  ,['四十五年，周君之秦客謂周（最）［聚］曰：「公不若譽秦王之孝，因以應為太后養地，秦王必喜，是公有秦交。', '赧王四十五年，周君派往秦國的使者對周聚說：「您不如稱讚秦王孝順，趁機請把應地獻給太后作為養地，秦王一定高興，您就能和秦國建立交情。']
  ,['交善，周君必以為公功。', '交情若好，周君一定會把它算作您的功勞。']
  ,['交惡，勸周君入秦者必有罪矣。', '交情若變壞，當初勸周君親近秦國的人就一定有罪了。』']
  ,['」秦攻周，而周聚謂秦王曰：「為王計者不攻周。', '秦國攻打周時，周聚對秦王說：「替大王計算，不應攻打周國。']
  ,['攻周，實不足以利，聲畏天下。', '攻打周國實際得不到多少利益，名聲上卻會使天下害怕秦國。']
  ,['天下以聲畏秦，必東合於齊。', '天下諸侯因害怕秦國，必定向東聯合齊國。']
  ,['兵獘於周。', '秦軍也會在周地疲敝。']
  ,['合天下於齊，則秦不王矣。', '如果天下聯合齊國，秦國就不能稱霸天下。']
  ,['天下欲獘秦，勸王攻周。', '天下正想消耗秦國，所以才勸大王攻打周國。']
  ,['秦與天下獘，則令不行矣。', '秦國若與天下一起疲敝，政令就無法推行了。」']
  ,['五十八年，三晉距秦。', '赧王五十八年，韓、魏、趙三國聯合抵抗秦國。']
  ,['周令其相國之秦，以秦之輕也，還其行。', '周王派宰相前往秦國，但秦國輕視周王室，宰相只好返回。']
  ,['客謂相國曰：「秦之輕重未可知也。', '有賓客對宰相說：「秦國究竟重視還是輕視您，現在還不能確定。']
  ,['秦欲知三國之情。', '秦國只是想知道三晉的情勢。']
  ,['公不如急見秦王曰『請為王聽東方之變』，秦王必重公。', '您不如趕快拜見秦王說：『請讓我替大王探聽東方的變化。』秦王一定會重視您。']
  ,['重公，是秦重周，周以取秦也；', '秦王重視您，就是秦國重視周王室，周國便可以藉此取得秦國的支持；']
  ,['齊重，則固有周聚以收齊：是周常不失重國之交也。', '如果齊國重視周聚，周國本來就有周聚可以爭取齊國；這樣周國始終不會失去與強國交往的機會。』']
  ,['」秦信周，發兵攻三晉。', '秦國相信了周國，出兵攻打三晉。']
  ,['五十九年，秦取韓陽城負黍，西周恐，倍秦，與諸侯約從，將天下銳師出伊闕攻秦，令秦無得通陽城。', '赧王五十九年，秦國攻取韓國的陽城和負黍；西周害怕，背離秦國，與諸侯訂立合縱盟約，準備率天下精銳軍隊從伊闕攻秦，使秦軍無法通往陽城。']
  ,['秦昭王怒，使將軍摎攻西周。', '秦昭王大怒，派將軍摎攻打西周。']
  ,['西周君犇秦，頓首受罪，盡獻其邑三十六，口三萬。', '西周君逃到秦國，叩頭請罪，把三十六座城邑和三萬人口全部獻給秦國。']
  ,['秦受其獻，歸其君於周。', '秦國接受他的獻納，把西周君送回周地。']
  ,['周君、王赧卒，周民遂東亡。', '西周君和赧王相繼去世，周地百姓於是向東逃亡。']
  ,['秦取九鼎寶器，而遷西周公於憚狐。', '秦國取得九鼎和珍貴器物，把西周公遷徙到憚狐。']
  ,['後七歲，秦莊襄王滅東（西）周。', '七年後，秦莊襄王滅掉東周。']
  ,['東西周皆入於秦，周既不祀。', '東周和西周都併入秦國，周朝的祭祀也就中斷了。']
  ,['太史公曰：學者皆稱周伐紂，居洛邑，綜其實不然。', '太史公說：學者都說周朝伐紂後住在洛邑，綜合史實來看並不是這樣。']
  ,['武王營之，成王使召公卜居，居九鼎焉，而周復都豐、鎬。', '武王營建洛邑，成王派召公占卜是否適合建都，並把九鼎安置在那裡；但周朝後來仍以豐、鎬為都城。']
  ,['至犬戎敗幽王，周乃東徙於洛邑。', '直到犬戎擊敗幽王，周朝才向東遷到洛邑。']
  ,['所謂「周公葬（我）［於］畢」，畢在鎬東南杜中。', '所謂「周公葬在畢」，畢地位於鎬京東南的杜地之中。']
  ,['秦滅周。', '秦國滅亡了周朝。']
  ,['漢興九十有餘載，天子將封泰山，東巡狩至河南，求周苗裔，封其後嘉三十里地，號曰周子南君，比列侯，以奉其先祭祀。', '漢朝建立九十多年後，天子準備封禪泰山，向東巡狩到河南，尋找周王室的後裔；把周王后代嘉封在三十里土地上，稱為周子南君，地位相當於列侯，讓他奉祀祖先。']
  ,['八年初監謗芮伯良夫戒百官於朝', '八年，開始設置監察制度；芮伯良夫在朝廷告誡百官。']
  ,['十一年西戎入於犬丘', '十一年，西戎攻入犬丘。']
  ,['十九年曹夷伯薨', '十九年，曹夷伯去世。']
  ,['二十二年大旱陳幽公薨', '二十二年，大旱；陳幽公去世。']
  ,['二十三年大旱宋僖公薨', '二十三年，大旱；宋僖公去世。']
  ,['二十四年大旱杞武公薨', '二十四年，大旱；杞武公去世。']
  ,['宣王', '宣王。']
  ,['名靖', '宣王名靖。']
  ,['元年甲戌春正月王即位周定公召穆公輔政復田賦作戎車燕恵侯薨', '宣王元年甲戌，春正月，宣王即位；周定公、召穆公輔佐政事，恢復田賦制度並製造戰車；燕惠侯去世。']
  ,['二年錫大師皇父司馬休父命魯慎公薨曹公子蘇弒其君幽伯疆', '二年，宣王賜命太師皇父和司馬休父；魯慎公去世；曹國公子蘇殺死國君幽伯疆。']
  ,['四年王命蹶父如韓韓侯來朝', '四年，宣王命蹶父出使韓國；韓侯入朝。']
